	["1 misión que aún no haces."] = "1 个尚未完成的任务。",
	["1 muerte"] = "1 次死亡",
	["1 más sin XP conocida: no cuenta."] = "另有 1 个经验未知：不计入。",
	["1 nivel"] = "1 级",
	["1 objeto más es de un jefe que aún no descubres."] = "另有 1 件物品来自你尚未发现的首领。",
	["1 para después"] = "以后可接 1 个",
	["1 para recoger"] = "1 个可接取",
	["1 para recoger ahora"] = "1 个现在可接取",
	["1 punto libre"] = "1 个未分配点数",
	["1 resultado"] = "1 个结果",
	["1 tótem puesto"] = "已放置 1 个图腾",
	["1. Llega al nivel 40. La montura y la equitación se compran a la vez: junta el oro mientras subes."] = "1. 达到 40 级。坐骑和骑术要同时购买：升级时攒好金币。",
	["2. Ve con el instructor de equitación de tu raza y aprende la de aprendiz."] = "2. 去找你种族的骑术训练师，学习初级骑术。",
	["3 de XP, 3 de oro, 3 de XP, 20 de tu profesión y 3 de clase para un objeto único."] = "3 个经验任务、3 个赚钱任务、3 个经验任务、20 个专业材料，以及 3 个职业任务换取一件独特物品。",
	["3. Compra la montura con el vendedor de tu raza (al lado del instructor) y úsala para aprenderla."] = "3. 向你种族的商人（就在训练师旁边）购买坐骑，然后使用它来学会。",
	["4. A nivel 60, el mismo instructor enseña la de oficial y el vendedor tiene las rápidas."] = "4. 60 级时，同一位训练师会教授中级骑术，商人也出售快速坐骑。",
	["A %s"] = "距离 %s",
	["A %s le queda poco"] = "%s快消失了",
	["A Entrañas se baja por elevadores desde las ruinas de la capital de Lordaeron."] = "要去幽暗城，得从洛丹伦旧都的废墟搭升降梯下去。",
	["A Mis planes"] = "加入我的计划",
	["A Ragnaros no le gusta que lo despierten antes de tiempo, y su mayordomo Executus lo paga caro."] = "拉格纳罗斯不喜欢被提前唤醒，他的管理者埃克索图斯为此付出了惨痛的代价。",
	["A Silithus se entra desde el Cráter de Un'Goro."] = "从安戈洛环形山可以进入希利苏斯。",
	["A distancia"] = "远程",
	["A entregar tus misiones"] = "去交付你的任务",
	["A la entrada de Ventormenta, estatuas de los grandes héroes de la Segunda Guerra reciben a los visitantes."] = "在暴风城的入口，第二次战争英雄们的雕像迎接着来访者。",
	["A la vista: %d de la manada · %d de tu grupo"] = "视野中：狼群 %d 人 · 队伍 %d 人",
	["A las demás les dice qué les falta: tu nivel o una misión antes."] = "其他任务会显示还缺什么：你的等级或前置任务。",
	["A los lados del modelo, un botón por ranura: un clic oculta esa pieza y otro la vuelve a poner."] = "模型两侧每个栏位各有一个按钮：点一下隐藏该部位，再点一下重新穿上。",
	["A mitad de la pelea aparecen espectros de hielo: mátenlos rápido o usen ataques en área."] = "战斗进行到一半会出现冰霜幽灵：尽快击杀，或使用范围攻击。",
	["A mitad de la pelea se protege con un escudo y prepara una gran explosión: cuando lo veas brillar, ¡aléjate de él!"] = "战斗进行到一半时，他会套上护盾并准备一次大爆炸：看到他发光时，赶紧远离他！",
	["A nivel 10 haces las misiones para domar a tu primera mascota."] = "10 级时你要做任务来驯服你的第一只宠物。",
	["A nivel 20 aprendes Lobo fantasmal: ¡te vuelves un lobo como yo! Corre, que te echo una carrera."] = "20 级时你会学会幽魂之狼：你会变成一匹跟我一样的狼！来吧，我们比赛跑。",
	["A nivel 60 sigue la rápida: equitación de oficial y una montura épica."] = "60 级之后是快速坐骑：中级骑术加一匹史诗坐骑。",
	["A probar"] = "试一试",
	["A quién ir"] = "找谁",
	["A su entrenador"] = "去找它的训练师",
	["A tu gusto"] = "随你喜好",
	["A tu lado"] = "在你身边",
	["A tu nivel los enemigos caen rápido: remata con 3 puntos de combo."] = "在你这个等级敌人倒得很快：攒 3 个连击点数就终结。",
	["A un clic"] = "一键直达",
	["A veces"] = "有时",
	["A veces el golpe ni te toca."] = "有时攻击根本碰不到你。",
	["A veces pescas cajas y botellas con mensajes que empiezan una misión."] = "有时你会钓到箱子和装着信的瓶子，可以开始一个任务。",
	["A veces salen gemas al minar: guárdalas, porque varias profesiones las usan en sus recetas."] = "采矿时有时会挖到宝石：收好，好几个专业的配方都用得到。",
	["Abajo"] = "向下",
	["Abajo del modelo, elige lo que hace tu personaje (caminar, bailar, saludar...) y páusalo."] = "在模型下方选择角色的动作（行走、跳舞、挥手……），还可以暂停。",
	["Abalorio"] = "饰品",
	["Abalorios"] = "饰品",
	["Abandonar"] = "放弃",
	["Abandonar marcadas (%d)"] = "放弃已标记的（%d）",
	["Abandonaste %d misiones"] = "你放弃了 %d 个任务",
	["Abierta"] = "已开放",
	["Abiertas"] = "已打开",
	["Abrazo vampírico: tu daño de sombras te cura."] = "吸血鬼的拥抱：你的暗影伤害会治疗你。",
	["Abre Heridas profundas."] = "解锁重伤。",
	["Abre Paisaje y gráficos"] = "打开风景与图形",
	["Abre Recolección. Con «ruta», crea y sigue una ruta de farmeo en tu zona."] = "打开采集。加上“ruta”可在你所在的区域创建并跟随一条采集路线。",
	["Abre desde el sigilo para empezar con ventaja."] = "从潜行中起手，开局就占优势。",
	["Abre el mapa del juego en esta misma zona. En combate el mapa del juego no se abre desde Alfa."] = "在同一区域打开游戏地图。战斗中无法从 Alfa 打开游戏地图。",
	["Abre el mapa y haz clic derecho (o Mayús+clic) donde quieras uno: le pones nombre, ícono y color, y la flecha te lleva cuando quieras. En el mapa del juego, Mayús+clic derecho."] = "打开地图，在想要的位置右键点击（或 Shift+点击）：设置名称、图标和颜色，箭头随时都能带你过去。在游戏地图上则用 Shift+右键。",
	["Abre el modo pesca (aquí, con /alfa pesca o al ponerte la caña) y pulsa %s: tu tecla te pone el equipo, el cebo, lanza y recoge cuando salpica."] = "打开钓鱼模式（在这里、用 /alfa pesca 或装备鱼竿时），然后按 %s：你的按键会帮你换上装备、上鱼饵、抛竿，并在水花溅起时收竿。",
	["Abre el modo pesca y elige tu tecla: te pone el equipo, el cebo, lanza y recoge cuando salpica."] = "打开钓鱼模式并选择你的按键：它会帮你换上装备、上鱼饵、抛竿，并在水花溅起时收竿。",
	["Abre el modo pesca y pulsa tu tecla: lo que saques aparece aquí."] = "打开钓鱼模式并按你的按键：钓到的东西会显示在这里。",
	["Abre la Cocina del juego (el botón lo hace) y vuelve a pulsar."] = "打开游戏的烹饪窗口（按钮会帮你打开），然后再按一次。",
	["Abre la Enciclopedia y en la ficha del objeto toca «Agregar a mi ruta»."] = "打开百科，在物品详情页点击“加入我的路线”。",
	["Abre la casa de subastas para escanear."] = "请打开拍卖行进行扫描。",
	["Abre la casa de subastas y pulsa «Escanear con Alfa» para saber cuánto valen tus objetos."] = "打开拍卖行并点击“用 Alfa 扫描”，就能知道你的物品值多少钱。",
	["Abre la guía de Alfa que te lleva a conseguir este objeto."] = "打开能带你获得此物品的 Alfa 指南。",
	["Abre la pelea a distancia antes de que llegue."] = "在它靠近之前先远程开怪。",
	["Abre la pelea: te acerca al enemigo y te da ira."] = "开场技能：让你冲到敌人身边并获得怒气。",
	["Abre la siguiente fila."] = "解锁下一排。",
	["Abre la ventana Historias."] = "打开“故事”窗口。",
	["Abre la ventana de clic para lanzar de Blizzard para que armes ahí los mismos clics y cures igual en sus marcos de grupo (el juego no deja que un addon los copie)."] = "打开暴雪的点击施法窗口，在那里设置相同的点击，在它的队伍框体上同样治疗（游戏不允许插件复制它们）。",
	["Abre la ventana de talentos del juego una vez o espera unos segundos: en cuanto Alfa la lea, te dice qué poner. Mientras, abajo ves tu build."] = "打开一次游戏的天赋窗口或稍等几秒：Alfa 一读取到，就会告诉你该点什么。在此期间，下方显示你的方案。",
	["Abre la ventana de tu profesión una vez y Alfa leerá tus recetas para decirte cuáles te dejan ganancia."] = "打开一次你的专业窗口，Alfa 就会读取你的配方，告诉你哪些能赚钱。",
	["Abre la ventana principal de Alfa."] = "打开 Alfa 主窗口。",
	["Abre o cierra el mapa de Alfa"] = "打开或关闭 Alfa 地图",
	["Abre siempre con Cargar y pon Desgarrar al empezar la pelea."] = "总是用冲锋开怪，战斗一开始就挂上撕裂。",
	["Abre siempre desde el sigilo con tu ataque más fuerte."] = "总是在潜行中用你最强的攻击起手。",
	["Abre su ficha."] = "打开它的详情页。",
	["Abre tus bolsas con su tecla o con el botón de la mochila."] = "用背包键或行囊按钮打开你的背包。",
	["Abre tus bolsas con tu tecla (%s)."] = "用你的按键（%s）打开背包。",
	["Abre un susurro con tu mensaje listo. Si no está conectado, el juego te lo dirá."] = "打开密语并填好你的消息。如果对方不在线，游戏会提示你。",
