	["Acepta invitaciones de grupo de tus amigos y de tu hermandad."] = "接受好友和公会成员的组队邀请。",
	["Acepta por ti"] = "替你接受",
	["Acepta una invocación al momento, salvo en combate."] = "立即接受召唤，战斗中除外。",
	["Acepta una resurrección en cuanto se puede. Nunca en Hardcore."] = "一有机会就接受复活。硬核模式下绝不接受。",
	["Acepta y entrega las demás (normales, diarias y semanales). Nunca las grises ni las que piden oro o materiales."] = "接受并交付其余任务（普通、日常和周常）。绝不接灰色任务，也不接要求金币或材料的任务。",
	["Aceptar"] = "确定",
