	["Cerrotajo es el primer pueblo orco grande que encuentras en Durotar; desde ahí se cuida el camino entre el Valle de los Retos y Orgrimmar."] = "剃刀岭是你在杜隆塔尔遇到的第一个大型兽人城镇；他们在那里守护试炼谷和奥格瑞玛之间的道路。",
	["Chamán"] = "萨满祭司",
