	["Colores de clase en los marcos, un cuadro de información más útil, el probador mejorado, la siguiente parada en los vuelos y sin voces de error. Cada una se apaga abajo cuando quieras."] = "框体上的职业颜色、更实用的鼠标提示、改进的试衣间、飞行中的下一站，以及静音错误语音。每一项都可以随时在下方关闭。",
