	["Combustión: tus hechizos de fuego hacen más críticos un rato."] = "燃烧：你的火焰法术在一段时间内更容易暴击。",
	["Combínala con Encantamiento para desencantar lo que coses y no uses."] = "搭配附魔，就能分解你缝制了却用不上的东西。",
	["Combínala con Herboristería: así recoges tú lo que necesitas."] = "搭配草药学：这样你需要的材料就能自己采。",
	["Combínala con Minería: casi todo lo que fabricas lleva metal."] = "搭配采矿：你制造的几乎所有东西都需要金属。",
	["Combínalo con Sastrería: la tela te da objetos verdes para desencantar."] = "搭配裁缝：布料能给你可以分解的绿色物品。",
	["Come y bebe entre peleas: recuperas vida y maná mucho más rápido."] = "战斗间隙吃喝：生命值和法力值恢复得快得多。",
