	["Completas"] = "完整",
	["Componentes"] = "材料",
	["Compra lo que tu paso necesita si el comerciante lo vende. Nada de más de 50 de oro."] = "如果商人有卖，就购买你当前步骤需要的东西。不超过 50 金币。",
	["Compra tu montura con %s"] = "向%s购买你的坐骑",
	["Comprar"] = "购买",
	["Comprar comida y bebida"] = "购买食物和饮料",
	["Comprar lo que pide tu guía"] = "购买指南要求的东西",
	["Comprar otra casilla del banco"] = "购买另一个银行栏位",
	["Comprar y vender con otros"] = "与其他玩家买卖",
	["Comunidad"] = "社区",
	["Común"] = "普通",
	["Con 10 de furia o más lo lanzas."] = "怒气达到 10 点即可施放。",
	["Con Cocina puedes encender tu propia fogata en cualquier lado."] = "学会烹饪后，你在哪里都能点燃自己的篝火。",
	["Con Redención reviven tus compañeros caídos: en una mazmorra vale oro."] = "救赎能复活倒下的同伴：在地下城里非常宝贵。",
	["Con aullido"] = "带狼嚎",
	["Con buena reputación, los vendedores de esa facción te hacen descuento."] = "声望够高时，该阵营的商人会给你打折。",
	["Con calma, nos pasa a todos. Mira qué te pegó y vuelve con todo."] = "别急，谁都会这样。看看是什么打倒了你，然后全力回来。",
	["Con dos armas pega más rápido: guarda maná para el final."] = "他双持武器，攻击更快：留好法力值应付最后阶段。",
	["Con el correo puedes enviar contra reembolso: mandas el objeto y cobras al entregarlo."] = "邮件可以货到付款：你寄出物品，对方收货时你就收到钱。",
	["Con el cuadro oculto en combate, mantén presionado Mayús para verlo."] = "战斗中鼠标提示被隐藏时，按住 Shift 即可查看。",
	["Con el cursor encima no se cierra."] = "鼠标停在上面时不会关闭。",
	["Con el entrenador más cercano en tu camino."] = "附带你路线上最近的训练师。",
	["Con el modo pesca abierto y alguna meta, la ventanita de metas se ve sola."] = "打开钓鱼模式并设有目标时，目标小窗口会自动显示。",
	["Con el modo pesca abierto, esta tecla lo hace todo: equipo, cebo, lanzar y recoger. Al cerrarlo vuelve a ser la de siempre."] = "打开钓鱼模式时，这个按键包办一切：装备、鱼饵、抛竿和收竿。关闭后，按键恢复原本功能。",
	["Con el modo pesca abierto, un aviso suave para volver a lanzar."] = "打开钓鱼模式时，用轻柔的提示提醒你重新抛竿。",
	["Con el tiempo, los magos humanos se reunieron en Dalaran, que se volvió la ciudad de la magia de los Reinos del Este."] = "后来，人类法师们聚集到达拉然，这里成了东部王国的魔法之城。",
	["Con la interfaz de mando el mapa del juego se abre con su tecla."] = "使用手柄界面时，游戏地图用它自己的按键打开。",
	["Con la interfaz para mando, Alfa deja las bolsas del juego. Igual puedes abrir la ventana de Alfa desde aquí."] = "使用手柄界面时，Alfa 会保留游戏自带的背包。你仍可以从这里打开 Alfa 窗口。",
	["Con la tecla en Espacio, Mayús+Espacio salta mientras el modo está abierto."] = "按键设为空格时，模式开启期间按 Shift+空格 跳跃。",
	["Con las de Alfa ves todo en una ventana: tres vistas, búsqueda, la barra de tus bolsas y qué vender cuando se llenan."] = "使用 Alfa 的背包，一个窗口就能看到全部：三种视图、搜索、背包栏，以及背包满时该卖什么。",
	["Con mando, se quedan las bolsas del juego"] = "使用手柄时保留游戏背包",
	["Con o sin Mayús, Ctrl o Alt. No lanza nada: aquí ves qué lanzaría sobre tu compañero."] = "可搭配 Shift、Ctrl 或 Alt。不会施放任何法术：这里只显示会对队友施放什么。",
	["Con poca vida llama a dos ayudantes: si a él le queda poco, terminen con él; si no, maten a los ayudantes."] = "血量低时他会召唤两个帮手：如果他快死了就先解决他；否则先杀帮手。",
	["Con poca vida se convierte en serpiente y pega más fuerte: guarda tus mejores ataques para ese momento."] = "血量低时他会变成毒蛇，打得更痛：把最强的攻击留到那时。",
	["Con qué prioridad sugiere Alfa. Automática: la de tus talentos o, mientras subes, la de tu clase."] = "Alfa 按哪种优先级给出建议。自动：按你的天赋，升级期间则按你的职业。",
	["Con reputación %s"] = "声望达到%s",
	["Con sonido"] = "带声音",
	["Con tu build, Alfa sabe qué estadísticas te sirven y qué equipo buscar."] = "有了方案，Alfa 就知道哪些属性对你有用、该找什么装备。",
	["Con tu punto libre se compra 1 rango de %s:"] = "用你的未分配点数点出 1 级%s：",
	["Con tu ritual de invocación y la ayuda de dos compañeros, traes a otro miembro del grupo hasta donde estés."] = "借助召唤仪式和两名同伴的帮助，你可以把另一名队友召唤到你身边。",
	["Con tus %d puntos libres se compran %d rangos de %s:"] = "用你的 %d 个未分配点数，点出 %d 级%s：",
	["Con un brillo suave"] = "带柔和光芒",
	["Con un enemigo elegido, antes de empezar la pelea, y transparente para que no estorbe."] = "选中敌人后、战斗开始前显示，并且半透明以免碍事。",
	["Concurso"] = "大赛",
	["Concurso de pesca de Tuercespina"] = "荆棘谷钓鱼大赛",
	["Configura tu Alfa"] = "设置你的 Alfa",
	["Configuración terminada"] = "设置完成",
	["Configuración y ayuda"] = "设置与帮助",
	["Configurar"] = "设置",
	["Configurar con el asistente"] = "使用向导设置",
	["Confirmado por Blizzard (su noticia del sistema de Legado de WoW Forever): los 65 retos de 1 punto, el tope de 16 por personaje, los tres árboles, los cuatro premios del registro y lo del modo extremo."] = "经暴雪确认（其关于 WoW Forever 传承系统的公告）：65 个各 1 点的挑战、每个角色 16 点上限、三棵树、进度的四个奖励，以及硬核模式的规则。",
	["Conflagrar: consume tu Inmolar para un golpe fuerte."] = "燃烧：消耗你的献祭，打出一记重击。",
	["Congela a los que están cerca: si peleas de lejos, aléjate."] = "他会冻住身边的人：远程玩家请站远一点。",
	["Congela al monstruo con Nova de escarcha y aléjate antes de seguir lanzando."] = "用冰霜新星冻住怪物，拉开距离后再继续施法。",
	["Congela en el lugar y lanza rayos: si peleas de lejos, sepárate del grupo."] = "她会把人定在原地并施放闪电：远程玩家请和队友分散站位。",
	["Congelas y frenas a los monstruos para que nunca te alcancen: el mago más seguro para subir."] = "冻结并减速怪物，让它们永远碰不到你：升级最安全的法师。",
	["Conjúralas fuera de combate."] = "非战斗时制造。",
	["Conocido"] = "熟悉",
	["Conseguir %d de %s"] = "获取 %d 个%s",
	["Conseguir %d × %s"] = "获得 %d × %s",
	["Conseguir %s"] = "获取%s",
	["Conseguir un objeto"] = "获得一件物品",
	["Consejo en el cuadro de los objetos"] = "物品鼠标提示中的建议",
	["Consejos"] = "提示",
	["Consejos de equipo apagados."] = "装备建议已关闭。",
	["Consejos para jugarlo"] = "玩法建议",
	["Consejos vistos"] = "已看过的建议",
	["Consejos: muchos"] = "建议：多",
	["Consejos: pocos"] = "建议：少",
	["Consejos: solo importantes"] = "建议：只看重要的",
	["Conserva %s: vale más de otra forma."] = "保留%s：用其他方式更值钱。",
	["Considerar desencantar"] = "考虑分解",
	["Consigue %s"] = "收集%s",
	["Consigue bolsas más grandes en cuanto puedas: más espacio, más botín."] = "尽快弄到更大的背包：空间更多，战利品更多。",
	["Consigue una caña de pescar"] = "弄一根鱼竿",
	["Consumibles"] = "消耗品",
	["Contar tu avance en el chat del grupo"] = "在队伍聊天中报告你的进度",
	["Contenta"] = "满足",
	["Contigo"] = "在身边",
	["Continuar"] = "继续",
	["Continuar mi ruta"] = "继续我的路线",
	["Contra jefes de nivel alto fallas mucho: esto lo arregla."] = "打高等级首领时你经常打空：这个能解决问题。",
	["Contra jefes fallas mucho: esto te ayuda."] = "打首领时你经常打空：这个能帮上忙。",
	["Contra no-muertos y demonios: Exorcismo pega muy fuerte."] = "对付亡灵和恶魔：驱邪术伤害非常高。",
	["Control de animación"] = "动作控制",
	["Contármela"] = "讲给我听",
	["Contármelo"] = "讲给我听",
	["Coordenadas en el mapa"] = "地图坐标",
	["Coordenadas en el minimapa"] = "小地图坐标",
	["Copia este texto (Ctrl+C) y pásalo a tu manada. Lo pegan en Importar."] = "复制这段文字（Ctrl+C）发给你的狼群。对方在“导入”中粘贴即可。",
	["Copia la cadena de abajo y pásala por el chat o por Discord: con Alfa la pegan en Importar y tienen tu mismo build."] = "复制下方的字符串，通过聊天或 Discord 发给别人：对方用 Alfa 在“导入”中粘贴，就能得到和你一样的方案。",
	["Copiar"] = "复制",
	["Copiar el Discord"] = "复制 Discord 链接",
	["Copiar y editar"] = "复制并编辑",
	["Coral"] = "珊瑚色",
	["Correr"] = "奔跑",
	["Cortar"] = "打断",
	["Costa Oscura está llena de ruinas élficas, como Ameth'Aran, de una época mucho más antigua."] = "黑海岸到处是精灵遗迹，例如亚米萨兰，它们来自一个古老得多的年代。",
	["Costasur y Molino Tarren están a un paso uno del otro, y la Alianza y la Horda se miran feo desde siempre."] = "南海镇和塔伦米尔近在咫尺，联盟和部落在这里向来互相敌视。",
	["Costuras, una abominación enorme, ataca Villa Oscura en una de las misiones más famosas del bosque."] = "巨大的憎恶斯迪克斯袭击夜色镇，是这片森林里最有名的任务之一。",
	["Crear %s ≈ %s"] = "制作%s ≈ %s",
	["Crear ruta"] = "创建路线",
	["Crecen hacia"] = "排列方向",
	["Criaturas de nivel %d a %d"] = "%d 到 %d 级的生物",
	["Criaturas raras y tesoros: dónde aparecen y lo que sueltan."] = "稀有生物和宝藏：出现地点和掉落物。",
	["Cristal"] = "玻璃",
	["Créditos y licencias"] = "致谢与许可证",
	["Crítico"] = "暴击",
	["Crítico con hechizos"] = "法术暴击",
	["Críticos enormes: matas antes de que te curen."] = "超高暴击：在对方被治疗之前就把他打死。",
	["Críticos más fuertes."] = "暴击更强。",
	["Críticos un poco más fuertes."] = "暴击稍强一些。",
	["Ctrl"] = "Ctrl",
	["Cuadro de información"] = "鼠标提示",
	["Cualquier criatura de su nivel"] = "同等级的任何生物",
	["Cualquier habilidad tuya que el juego resalte por un efecto."] = "游戏因某个效果而高亮的任何技能。",
	["Cualquier instructor de pesca te la enseña. Luego compra una caña y unas lombrices: con eso empiezas."] = "任何钓鱼训练师都能教你。然后买一根鱼竿和一些蚯蚓鱼饵：这样就能开始了。",
	["Cualquier profesión"] = "任意专业",
	["Cualquiera"] = "任意",
	["Cuando al monstruo le quede poca vida, usa Ejecutar (Alfa te avisa)."] = "怪物血量低时使用斩杀（Alfa 会提醒你）。",
	["Cuando aprendas %s, también."] = "学会%s后也会提醒。",
	["Cuando aprendas %s, te avisa al momento de usarlas."] = "学会%s后，会在该使用时提醒你。",
	["Cuando aprendes un rango nuevo, un aviso ofrece cambiarlo en tus barras."] = "学会新等级时，会提示你在动作条上替换。",
	["Cuando buscas algo en la subasta, Alfa guarda el precio más bajo que ves."] = "你在拍卖行搜索时，Alfa 会记下你看到的最低价。",
	["Cuando el Pozo de la Eternidad explotó, el gran continente antiguo se partió en pedazos. A eso le llaman la Gran División."] = "永恒之井爆炸时，古老的大陆四分五裂。人们称之为大分裂。",
	["Cuando el juego termina de cargar, Alfa revisa lo que elegiste aquí y lo vuelve a poner si algo lo cambió. Si después los cambias en el menú del juego, Alfa se queda con lo nuevo."] = "游戏加载完成时，Alfa 会检查你在这里的选择，如果有东西改动了它们，就重新套用。如果你之后在游戏菜单中更改，Alfa 会保留新的设置。",
	["Cuando entras a una posada o ciudad, y cuando tu XP descansada se acaba."] = "进入旅店或城镇时，以及精力充沛经验用完时。",
	["Cuando hay un festival, vale la pena darse una vuelta: casi siempre trae mascotas, ropa o comida que no salen el resto del año."] = "有节日的时候很值得去逛逛：几乎总会有一年中其他时候拿不到的宠物、服装或食物。",
	["Cuando hay varias para elegir, toma la que más te sirve."] = "有多个可选时，选对你最有用的那个。",
	["Cuando huelo salchichas se me olvida todo. Bueno, menos tú."] = "一闻到香肠的味道我就什么都忘了。嗯，除了你。",
	["Cuando la Legión volvió en la Tercera Guerra, Malfurion y Tyrande hicieron sonar el Cuerno de Cenarius para despertar a los druidas dormidos."] = "燃烧军团在第三次战争中卷土重来时，玛法里奥和泰兰德吹响了塞纳留斯之角，唤醒沉睡的德鲁伊。",
	["Cuando la meta de ahora de tu plan es un lugar, la flecha lo toma sin que hagas clic."] = "当计划的当前目标是一个地点时，箭头会自动指向它，无需点击。",
	["Cuando le baja la vida aturde a todos y corre a su cofre a cambiar de arma: espérenlo, no lo persigan."] = "血量下降时他会击晕所有人，跑到箱子那里换武器：等他回来，别去追。",
	["Cuando lleves algo, Alfa te dice si conviene venderlo, subastarlo o transformarlo, y cuánto ganas."] = "当你携带物品时，Alfa 会告诉你该卖给商人、拍卖还是加工，以及能赚多少。",
	["Cuando los orcos se volvieron brujos, dejaron de oír a los elementos. Thrall les devolvió ese camino."] = "兽人变成术士之后，就听不见元素的声音了。是萨尔把这条道路还给了他们。",
	["Cuando otro lobo con Alfa comparta su ubicación, aparece aquí y en tu mapa. Para que la manada crezca, invita a tus amigos: que instalen Alfa, acepten compartir y entren al Discord de La Jauría."] = "当其他使用 Alfa 的狼共享位置时，会出现在这里和你的地图上。想让狼群壮大，就邀请你的朋友：安装 Alfa、同意共享并加入 La Jauría 的 Discord。",
	["Cuando se abre una misión de clase para ti, te ofrece su guía."] = "有适合你的职业任务开放时，提供其指南。",
	["Cuando se escapa"] = "鱼跑掉时",
	["Cuando se llenan"] = "背包满时",
	["Cuando te quedes sin maná, cambia a forma felina para terminar la pelea."] = "法力值用完时，切换到猎豹形态结束战斗。",
	["Cuando tengas pescado que sepas cocinar, aparece aquí."] = "当你有会烹饪的鱼时，就会显示在这里。",
	["Cuando tu paso lo pide y hablas con su posadero. Nunca en otra posada."] = "当你的步骤需要、并且你与对应的旅店老板交谈时。绝不在其他旅店。",
	["Cuando tú o tu grupo peleen, aquí sale quién hace más daño."] = "当你或你的队伍战斗时，这里会显示谁的伤害最高。",
	["Cuando un elfo de la noche muere, su espíritu toma forma de fuego fatuo y corre más rápido hasta su cuerpo."] = "暗夜精灵死后，灵魂会化为小精灵，更快地跑回尸体。",
	["Cuando una pieza baja de este porcentaje."] = "当某件装备低于此百分比时。",
	["Cuando venzas a tu primer jefe, tu progreso aparecerá aquí."] = "击败第一个首领后，你的进度就会显示在这里。",
	["Cuando ya casi se rompe."] = "快要损坏时。",
