	["Cuánto dura un aviso en pantalla"] = "提醒在屏幕上显示多久",
	["Cuánto falta para tu siguiente golpe automático, con cada mano. Ayuda a meter Embate o Golpe heroico sin perder golpes."] = "显示每只手距离下一次自动攻击还有多久。帮助你插入猛击或英勇打击而不浪费攻击。",
	["Cuánto más brillan las luces que en una pantalla normal. El juego no pasa del máximo de tu monitor."] = "光源比普通屏幕亮多少。游戏不会超过你显示器的最大亮度。",
	["Cuánto oro"] = "多少金币",
	["Cuánto pasto, flores y hierbas cubren el suelo."] = "地面上覆盖多少草、花和杂草。",
	["Cuánto se ve el fondo de las ventanas de chat; en cero solo queda el borde."] = "聊天窗口背景的可见程度；为零时只剩边框。",
