	["DPS"] = "DPS",
	["DPS del arma"] = "武器 DPS",
	["Daga"] = "匕首",
	["Dale de comer a tu mascota para que esté contenta y pegue más."] = "喂食你的宠物，让它保持快乐，打得更痛。",
	["Dale de comer para que esté feliz: pega más fuerte."] = "喂食让它保持高兴：它的伤害会更高。",
