	["Dar al chat el estilo de Alfa"] = "让聊天使用 Alfa 风格",
	["Dar al minimapa el estilo de Alfa"] = "让小地图使用 Alfa 风格",
	["Darnassus está en las ramas de Teldrassil. La suma sacerdotisa Tyrande Susurravientos gobierna desde el Templo de la Luna."] = "达纳苏斯位于泰达希尔的枝干上。大祭司泰兰德·语风在月神殿统治。",
	["Dath'Remar Caminante del Sol guió a los altos elfos hasta Quel'Thalas. De su linaje viene el príncipe Kael'thas."] = "达斯雷玛·逐日者带领高等精灵来到奎尔萨拉斯。凯尔萨斯王子就是他的后裔。",
	["Datos"] = "数据",
	["Datos curiosos de Lya, escritos por Alfa."] = "Lya 的趣闻，由 Alfa 撰写。",
	["Daño"] = "伤害输出",
	["Daño a distancia"] = "远程伤害",
	["Daño con el tiempo: ponla al empezar la pelea."] = "持续伤害：战斗开始时施放。",
	["Daño de arcos, armas de fuego y ballestas."] = "弓、枪械和弩的伤害。",
	["Daño de fuego con el tiempo."] = "持续火焰伤害。",
	["Daño del arma"] = "武器伤害",
	["Daño directo de fuego y sombras: matas antes de que el monstruo llegue."] = "火焰和暗影直接伤害：在怪物走到你面前之前就把它打死。",
	["Daño directo de tus armas y habilidades."] = "你的武器和技能的直接伤害。",
	["Daño en grupo de cinco: pegar fuerte sin robarle los monstruos al tanque."] = "五人小队输出：打得猛，又不抢坦克的仇恨。",
	["Daño extra después de recibir críticos."] = "受到暴击后获得额外伤害。",
