	["Daño periódico"] = "周期性伤害",
	["Daño por segundo"] = "每秒伤害",
	["Daño sobre tus enemigos"] = "敌人身上的伤害",
	["De 1 a 300"] = "从 1 到 300",
	["De 1 a 300, dónde pescar cerca de ti, equipo, cebos, misiones y el concurso."] = "从 1 到 300、你附近哪里能钓鱼、装备、鱼饵、任务和大赛。",
	["De Forever"] = "来自 Forever",
	["De arriba abajo: la primera que el juego te deja usar es la que sale en el ícono. Lo que el juego hace brillar pasa al frente; las de área salen con varios enemigos peleando. Solo aparecen las que ya aprendiste."] = "从上到下：游戏允许你使用的第一个就是图标上显示的那个。游戏点亮的技能会排到最前面；多个敌人参战时会出现范围技能。只显示你已学会的技能。",
	["De arriba abajo: la primera que el juego te deja usar es la que sale en el ícono; las de área, solo con 3 o más enemigos peleando."] = "从上到下：游戏允许你使用的第一个技能会显示在图标上；范围技能只在 3 个或更多敌人参战时使用。",
	["De clase"] = "职业",
	["De clase: %s"] = "职业：%s",
	["De este lugar Lya todavía no sabe datos curiosos. Elige una misión de la lista para leer su historia."] = "Lya 还不知道这个地方的趣闻。从列表中选一个任务来读它的故事吧。",
	["De este lugar todavía no sé mucho. ¿Vemos tus historias?"] = "这个地方我还不太了解。要看看你的故事吗？",
	["De fábrica el seguimiento muestra solo lo que estás haciendo; encendido, muestra el paso completo con sus notas."] = "默认情况下追踪器只显示你正在做的事；开启后会显示完整步骤及其备注。",
	["De la base de datos incluida"] = "来自内置数据库",
	["De la otra facción"] = "另一阵营",
	["De los que se presumen"] = "值得炫耀的一条",
	["De misión"] = "任务物品",
	["De nivel %.1f a %.1f, con unos %s de oro. Solo misiones que ya puedes tomar; lo que pide más nivel va después de un paso que lo espera."] = "从 %.1f 级到 %.1f 级，约赚 %s 金币。只包含你现在就能接的任务；需要更高等级的任务会放在等待升级的步骤之后。",
	["De todo %s, ¿qué rincón te gusta más?"] = "整个%s，你最喜欢哪个角落？",
	["De tu gente todavía no sé mucho. ¿Te cuento otra cosa?"] = "关于你的族人，我知道的还不多。要我讲点别的吗？",
	["Debajo del ícono: útil mientras aprendes."] = "显示在图标下方：学习时很有用。",
	["Dedo"] = "手指",
	["Defensa"] = "防御",
	["Deja que el tanque golpee primero unos segundos antes de usar tus golpes fuertes."] = "先让坦克打几秒，再使用你的强力攻击。",
	["Deja que la manada te vea en el mapa"] = "让狼群在地图上看到你",
	["Deja que tu mascota empiece la pelea y dispara cuando el monstruo la esté atacando."] = "让宠物先开怪，等怪物在打宠物时再射击。",
	["Deja solo lo esencial: tú, tu grupo, tus marcadores y el siguiente paso de la guía."] = "只保留必要内容：你、你的队伍、你的标记和指南的下一步。",
