	["Del motor de Alfa: al subir de nivel te muestra qué aprender y cuánto cuesta."] = "来自 Alfa 引擎：升级时显示可学的技能和费用。",
	["Del motor de Alfa: con el entrenador más cercano en tu camino."] = "来自 Alfa 引擎：附带你路线上最近的训练师。",
