	["Detrás de «%s» hay más de lo que parece. ¿Te la cuento?"] = "“%s”背后比看上去的还要多。要我讲给你听吗？",
	["Devolver"] = "复位",
	["Devolver los avisos a su lugar"] = "将提醒恢复原位",
	["Devuelve cada ajuste que Alfa tocó al valor que tenía antes y deja de mantenerlos."] = "把 Alfa 改动过的每项设置恢复为之前的数值，并停止保留它们。",
