	["Dibuja el arte completo de cada zona recortado a su forma, con las texturas de detalle incluidas. Sin ellas el mapa sigue completo, solo más suave entre zona y zona."] = "使用自带的细节贴图，按每个区域的形状绘制完整的区域图。没有这些贴图时地图依然完整，只是区域之间的过渡更柔和。",
	["Dibuja la ruta hasta tu objetivo: por dónde caminar, volar o navegar."] = "绘制前往目标的路线：在哪里步行、飞行或乘船。",
	["Dice en el chat qué misión perderías y te deja aceptarla a ti."] = "在聊天中说明你会失去哪个任务，并由你决定是否接受。",
	["Dicen que el Bosque del Ocaso se oscureció por estar tan cerca de Karazhan, y desde entonces vive en penumbra."] = "据说暮色森林因为离卡拉赞太近而变暗，从此一直笼罩在昏暗之中。",
	["Dicen que en Thelsamar venden morcilla. ¡Es casi una salchicha! Solo digo."] = "听说塞尔萨玛有卖血肠。那差不多就是香肠嘛！我只是说说。",
	["Diestro"] = "熟练",
	["Diez mil años atrás, Illidan creó en la cima de Hyjal un nuevo Pozo de la Eternidad, y sobre él se plantó Nordrassil."] = "一万年前，伊利丹在海加尔山顶创造了一口新的永恒之井，诺达希尔就种在它上面。",
	["Dinero de toda la cuenta"] = "整个账号的金币",
	["Dinero de tus personajes"] = "你各角色的金币",
	["Disciplina"] = "戒律",
	["Disciplina para subir"] = "戒律（升级）",
	["Dispara desde lejos: alguien debe ir por él."] = "他会在远处射击：得有人冲过去对付他。",
	["Disparo apuntado: tu disparo más fuerte."] = "瞄准射击：你最强的射击。",
	["Disparo arcano: instantáneo, úsalo cuando esté listo."] = "奥术射击：瞬发，冷却好就用。",
	["Disponible a nivel %d"] = "%d 级可接",
	["Distancia"] = "远程",
	["Distancia a la que ciudades, torres y cuevas conservan su detalle."] = "城市、塔楼和洞穴保留细节的距离。",
	["Distancia a la que el suelo conserva su forma completa."] = "地面保留完整形状的距离。",
	["Distancia de las placas"] = "姓名板距离",
	["Distancia de visión"] = "视距",
	["Distancia del pasto"] = "草地距离",
	["Distancia y velocidad"] = "距离与速度",
	["Doble clic derecho"] = "右键双击",
	["Doble clic derecho para lanzar"] = "右键双击抛竿",
	["Doble clic mientras pescas vuelve a lanzar"] = "钓鱼时双击重新抛竿",
	["Dolanaar es la aldea élfica en el camino a Darnassus; su posada huele a bosque."] = "多兰纳尔是通往达纳苏斯路上的精灵村庄；那里的旅店闻起来有森林的味道。",
	["Domingo de concurso"] = "大赛周日",
	["Dominio de bestias"] = "野兽控制",
	["Dominio de bestias para subir"] = "野兽控制（升级）",
	["Donde antes estaba el Pozo de la Eternidad hoy gira el Maelstrom, un remolino eterno en medio del Gran Mar."] = "永恒之井原来所在的地方，如今是大漩涡，在无尽之海中央永不停歇地旋转。",
	["Donde lo sacas: %s."] = "在哪里钓到：%s。",
	["Donde puedes seguir en varias zonas, toma la recomendada sin preguntar."] = "可以在多个区域继续时，不询问直接选择推荐的那个。",
	["Dormir"] = "睡觉",
	["Dos armas"] = "双持武器",
	["Dos armas y mucha ira. Furia pega más que Armas cuando tiene buen equipo, y Sed de sangre llega al nivel 40. Necesitas dos armas de una mano desde el nivel 20."] = "双持武器，怒气充足。装备好的时候狂怒比武器打得更痛，嗜血在 40 级获得。从 20 级起你需要两把单手武器。",
	["Dos clics y Alfa te lleva"] = "点两下，Alfa 就会带你去",
	["Dos manos"] = "双手",
	["Dos monstruos a la vez dejan de ser un problema."] = "同时面对两个怪物不再是问题。",
	["Dos profesiones de recolección: oro constante sin perder tiempo, justo cuando más lo necesitas."] = "两个采集专业：稳定赚金币又不浪费时间，正是最需要钱的时候。",
	["Drek'Thar, el viejo chamán ciego del clan Lobo Gélido, le enseñó a Thrall a hablar con los espíritus. ¡Un sabio de los lobos!"] = "霜狼氏族年迈的盲眼萨满德雷克塔尔教会了萨尔与灵魂交谈。狼族的智者！",
	["Drenar alma al rematar te da uno."] = "用吸取灵魂完成击杀可获得一个。",
	["Druida"] = "德鲁伊",
	["Druidas, guerreros y pícaros: si tu barra de forma o de actitud está vacía, Alfa te avisa y la llena con un clic."] = "德鲁伊、战士和潜行者：如果你的形态或姿态动作条是空的，Alfa 会提醒你，并一键帮你填满。",
	["Duelos"] = "决斗",
	["Duerme a un jugador y lanza sombras: interrúmpelo."] = "他会催眠一名玩家并施放暗影法术：打断他。",
	["Dun Algaz es el túnel enano que une Los Humedales con Loch Modan."] = "丹阿加兹是连接湿地和洛克莫丹的矮人隧道。",
	["Duplicar"] = "复制",
	["Durabilidad"] = "耐久度",
	["Duración"] = "时长",
	["Durante la pelea despierta a guardianes de piedra: alguien debe tanquearlos o mátenlos rápido."] = "战斗中他会唤醒石头守卫：要有人把它们坦住，或者尽快击杀。",
	["Durante siglos los druidas durmieron en el Sueño Esmeralda mientras las Centinelas cuidaban el bosque."] = "数百年来，德鲁伊在翡翠梦境中沉睡，哨兵们则守护着森林。",
	["Durotan y su clan Lobo Gélido se negaron a beber la sangre de Mannoroth. Gul'dan nunca se lo perdonó."] = "杜隆坦和他的霜狼氏族拒绝饮下玛诺洛斯之血。古尔丹从未原谅他。",
	["Durotar lleva el nombre de Durotan, el padre de Thrall y jefe del clan Lobo Gélido. Thrall honró su memoria al nombrar así la tierra de los orcos."] = "杜隆塔尔以杜隆坦命名，他是萨尔的父亲，也是霜狼氏族的酋长。萨尔用父亲的名字为兽人的土地命名，以纪念他。",
	["Dónde"] = "地点",
	["Dónde aprender Pesca y sus rangos. Se llenan al abrir la guía de pesca."] = "在哪里学习钓鱼及其等级。打开钓鱼指南后就会填入。",
	["Dónde empieza el paisaje lejano simplificado."] = "简化远景从哪里开始。",
	["Dónde entregar"] = "交任务地点",
	["Dónde está"] = "位置",
	["Dónde está cada uno, lo que vende, lo que suelta y sus misiones."] = "每个人的位置、出售的物品、掉落和任务。",
	["Dónde mandarlo"] = "发送到哪里",
	["Dónde sale"] = "来源",
	["Dónde se entrega"] = "交付地点",
	["Dónde se ven"] = "显示位置",
	["Editar"] = "编辑",
	["Edwin VanCleef, el jefe Defias, era maestro cantero. Cuando la nobleza no pagó la reconstrucción de Ventormenta, juró venganza."] = "迪菲亚的首领艾德温·范克里夫曾是石匠大师。贵族们不肯支付重建暴风城的工钱时，他发誓要复仇。",
	["Efecto activo"] = "效果生效中",
	["Efecto del vacío"] = "虚空效果",
	["Efectos"] = "特效",
	["Efectos de pantalla del juego"] = "游戏的屏幕效果",
	["Ej.: Comprar bolsas de 10 casillas"] = "例如：购买 10 格背包",
	["Ejecutar cuesta menos ira: rematas antes."] = "斩杀消耗的怒气更少：能更早终结敌人。",
	["Ejecutar más barato para rematar jefes."] = "更便宜的斩杀，方便收掉首领。",
	["El Alba Argenta pelea contra la Plaga sin el fanatismo de los Escarlatas, y recibe por igual a la Alianza y a la Horda."] = "银色黎明与天灾军团作战，却没有血色十字军那样的狂热，同样欢迎联盟和部落。",
	["El Bastión Plumaluna, en una isla frente a la costa, es el puesto de las centinelas élficas."] = "位于近海小岛上的羽月要塞，是精灵哨兵的据点。",
	["El Bosque del Ocaso y las Montañas Crestagrana también son tierras del reino, y piden ayuda porque los soldados no alcanzan."] = "暮色森林和赤脊山也是王国的领土，那里的人们在求援，因为士兵不够用。",
	["El Campamento Mojache es el hogar de la Horda en Feralas."] = "莫沙彻营地是部落在菲拉斯的家园。",
	["El Castillo de Colmillo Oscuro fue de Arugal, un mago de Dalaran que convocó a los worgen para pelear contra la Plaga y terminó perdiendo la razón."] = "影牙城堡曾属于阿鲁高，他是一位达拉然法师，召唤了狼人来对抗天灾军团，最后却失去了理智。",
	["El Claro de la Luna es un santuario de druidas; ahí se reúne el Círculo Cenarion."] = "月光林地是德鲁伊的圣地；塞纳里奥议会在那里聚会。",
	["El Codex no sabe de dónde sale; si ya la tienes, la ves en tu diario de monturas."] = "Codex 不知道它从哪里获得；如果你已拥有，可以在坐骑收藏中看到。",
	["El Cruce es un puesto de la Horda justo en medio de Los Baldíos, donde se juntan los caminos principales. De ahí su nombre."] = "十字路口是部落位于贫瘠之地正中央的据点，几条主要道路在这里交会。它的名字就是这么来的。",
	["El Culto de los Malditos lo fundó Kel'Thuzad: les prometía a los campesinos de Lordaeron una vida eterna y más justa."] = "诅咒神教是克尔苏加德创立的：他向洛丹伦的农民许诺永恒而更公平的生活。",
	["El Discord de La Jauría"] = "La Jauría 的 Discord",
	["El Fuerte Cenarion es la base del Círculo Cenarion en Silithus, frente a los qiraji."] = "塞纳里奥要塞是塞纳里奥议会在希利苏斯的基地，正面对着其拉虫人。",
	["El Gran Manitas Gelbin Mekkatorque es el líder de los gnomos."] = "大工匠格尔宾·梅卡托克是侏儒的领袖。",
	["El Guardián Remulos, hijo de Cenarius, cuida el Claro de la Luna desde su santuario."] = "塞纳留斯之子守护者雷姆洛斯在他的神殿守护着月光林地。",
	["El Horado Rajacieno y la Zahúrda Rajacieno son guaridas de los jabaespines, entre Los Baldíos y Las Mil Agujas."] = "剃刀沼泽和剃刀高地是野猪人的巢穴，位于贫瘠之地和千针石林之间。",
	["El Legado se abre con tu primer punto (casi siempre, al llegar a nivel 25), con la tecla Y o con su botón del menú."] = "获得第一点后（通常在达到 25 级时）传承就会开启，可以按 Y 键或通过菜单按钮打开。",
	["El Loto negro crece solo en zonas de nivel muy alto, y es tan raro que vale una fortuna."] = "黑莲花只生长在等级很高的区域，稀有到价值连城。",
	["El Loto negro es rarísimo: crece en Cuna del Invierno, las Estepas Ardientes, las Tierras de la Peste del Este y Silithus."] = "黑莲花极为稀有：生长在冬泉谷、燃烧平原、东瘟疫之地和希利苏斯。",
	["El Martillo Crepuscular tiene campamentos en Silithus, donde intenta invocar a los señores elementales."] = "暮光之锤在希利苏斯设有营地，企图在那里召唤元素领主。",
	["El Núcleo de Magma, en el fondo de la Montaña Roca Negra, es el hogar de Ragnaros, el Señor del Fuego."] = "熔火之心位于黑石山深处，是炎魔之王拉格纳罗斯的家。",
	["El Paso de la Muerte no tiene ni un pueblo: solo ogros, bestias y la sombra de Karazhan."] = "逆风小径连一个村庄都没有：只有食人魔、野兽和卡拉赞的阴影。",
	["El Paso de la Muerte une el Bosque del Ocaso con el Pantano de las Penas."] = "逆风小径连接暮色森林和悲伤沼泽。",
	["El Portal Oscuro está apagado en el Clásico. En Burning Crusade vuelve a abrirse rumbo a Terrallende."] = "黑暗之门在经典版中处于沉寂状态。到了燃烧的远征，它会再次开启，通往外域。",
	["El Portal Oscuro lo abrieron Medivh y Gul'dan juntos, cada uno desde su lado."] = "黑暗之门是麦迪文和古尔丹各自从两边一起打开的。",
	["El Puente Thandol, al norte, une Khaz Modan con Arathi; los Hierro Negro lo dejaron medio destruido."] = "北边的萨多尔大桥连接卡兹莫丹和阿拉希；黑铁矮人把它毁掉了一半。",
	["El Puerto de Menethil lleva el apellido de la familia real de Lordaeron. De ahí salen barcos a Theramore y a Auberdine."] = "米奈希尔港以洛丹伦王室的姓氏命名。从那里有船开往塞拉摩和奥伯丁。",
	["El Puesto Hachazo es el campamento de la Horda que tala Vallefresno."] = "碎木岗哨是部落在灰谷伐木的营地。",
	["El Refugio Roca del Sol es el hogar de los tauren en estas montañas."] = "烈日石居是牛头人在这片山区的家园。",
	["El Refugio de la Zaga es el campamento de la Alianza en Arathi, entre ruinas, trols y ogros."] = "避难谷地是联盟在阿拉希的营地，周围是废墟、巨魔和食人魔。",
	["El Refugio del Mariscal es el único campamento del cráter, y lo comparten todos."] = "马绍尔营地是火山口里唯一的营地，所有人共用。",
	["El SI:7 de Ventormenta y Ravenholdt son nombres que todo pícaro conoce."] = "暴风城的军情七处和拉文霍德是每个盗贼都知道的名字。",
	["El Sepulcro es el puesto de los Renegados en el bosque; desde ahí vigilan a los worgen y a los magos de Dalaran."] = "瑟伯切尔是被遗忘者在森林中的据点；他们从那里监视狼人和达拉然的法师。",
	["El Sindicato, los nobles caídos de Alterac, también asalta caminos y granjas por estas tierras."] = "辛迪加——奥特兰克的没落贵族们——也在这一带袭击道路和农场。",
	["El Sueño Esmeralda se está volviendo pesadilla: algo corrompe a los dragones verdes que lo cuidan."] = "翡翠梦境正在变成梦魇：有什么东西正在腐化守护它的绿龙。",
	["El Tranvía Subterráneo une Forjaz con Ventormenta por debajo de la tierra. Lo construyeron los gnomos."] = "矿道地铁在地下连接铁炉堡和暴风城。它是侏儒建造的。",
	["El Trono Helado es la armadura de hielo donde quedó atrapado Ner'zhul, en lo alto de la Corona de Hielo."] = "冰封王座是囚禁耐奥祖的冰之铠甲，位于寒冰皇冠之巅。",
	["El Valle Calcinado, al sur de la sierra, quedó quemado y lleno de elementales de fuego."] = "山脉南边的焦炭谷被烧得焦黑，到处是火元素。",
	["El Vigía de Morgan es el puesto de la Alianza en las estepas, desde donde vigilan la Montaña Roca Negra."] = "摩根的岗哨是联盟在平原上的据点，他们从那里监视黑石山。",
	["El aguante es tu mejor amigo: más vida para más Transfusión de vida."] = "耐力是你最好的朋友：生命值越多，生命分流用得越多。",
	["El almirante Daelin Valiente, padre de Jaina, cayó en Theramore tras atacar a la Horda. Su hija eligió la paz."] = "吉安娜的父亲戴林·普罗德摩尔上将攻击部落后，战死在塞拉摩。他的女儿选择了和平。",
	["El archidruida Fandral Corzocelada enseña en el Enclave Cenarion de Darnassus."] = "大德鲁伊范达尔·鹿盔在达纳苏斯的塞纳里奥区授课。",
	["El archidruida Fandral Corzocelada plantó Teldrassil con la esperanza de recuperar la inmortalidad que los elfos perdieron en el Monte Hyjal."] = "大德鲁伊范达尔·鹿盔种下了泰达希尔，希望找回精灵们在海加尔山失去的永生。",
	["El archidruida Hamuul Tótem de Runa enseña a los druidas tauren, y fue de los primeros tauren aceptados en el Círculo Cenarion."] = "大德鲁伊哈缪·符文图腾教导牛头人德鲁伊，他是最早被塞纳里奥议会接纳的牛头人之一。",
	["El arma principal debe ser la más lenta y fuerte; la secundaria, la más rápida."] = "主手武器应选最慢、最强的；副手选最快的。",
	["El aro y la cabecera del minimapa con tu estilo."] = "小地图的边框和标题栏使用你的风格。",
	["El banco está lleno: compra otra casilla o pon una bolsa más grande en el banco."] = "银行已满：购买另一个栏位，或在银行中放一个更大的背包。",
	["El barco goblin une Bahía del Botín con Trinquete, y lo pueden usar los dos bandos."] = "地精的船往返于藏宝海湾和棘齿城之间，两个阵营都能搭乘。",
	["El barón Osahendido manda en Stratholme como caballero de la muerte de la Plaga."] = "瑞文戴尔男爵以天灾军团死亡骑士的身份统治着斯坦索姆。",
	["El blanco de la interfaz y del cielo de día."] = "界面和白天天空的白色。",
	["El bonus de tu arma al máximo."] = "武器类型加成点满。",
	["El borde del minimapa, redondo o cuadrado («Minimapa cuadrado», arriba), y la barra con la zona y la hora toman el estilo que elijas, como la ventana del mapa. Al apagarlo vuelve el de siempre."] = "小地图的边框（圆形或方形，见上方“方形小地图”）以及显示区域和时间的栏会采用你选择的风格，就像地图窗口一样。关闭后恢复原样。",
	["El borde toma el color del perjuicio (magia, maldición, enfermedad o veneno) cuando tú lo puedes quitar."] = "当你能驱散时，边框会显示减益效果的颜色（魔法、诅咒、疾病或中毒）。",
	["El botón «Escanear con Alfa» bajo la ventana de la subasta."] = "拍卖行窗口下方的“用 Alfa 扫描”按钮。",
	["El brillo más alto que da tu monitor; viene en su caja o su ficha."] = "你的显示器能达到的最高亮度；可以在包装盒或规格表上找到。",
	["El brillo suave de luces y cielo en toda la pantalla."] = "整个屏幕上灯光和天空的柔和光晕。",
	["El brujo Zalazane les robó las Islas del Eco a los Lanza Negra con su vudú."] = "巫医扎拉赞恩用巫毒术从暗矛部族手中夺走了回音群岛。",
	["El buscador del motor está apagado (Ajustes > Descubrir): enciéndelo para que Alfa arme guías."] = "引擎的查询已关闭（设置 > 发现）：请开启，让 Alfa 能生成指南。",
	["El buscador no está disponible."] = "搜索功能不可用。",
	["El camino a Entrañas pasa por las ruinas de la Ciudad Capital de Lordaeron, donde Arthas mató a su padre."] = "通往幽暗城的路要经过洛丹伦首都的废墟，阿尔萨斯就是在那里杀死了他的父亲。",
	["El camino a la meta en el mapa del mundo y el minimapa: una línea o puntos donde caminas, líneas donde vuelas, navegas o montas, y los tramos que siguen más tenues."] = "在世界地图和小地图上显示通往目标的路线：步行段为线条或圆点，飞行、航行或乘坐段为线条，之后的路段颜色较淡。",
	["El camino en el mapa y el minimapa"] = "地图和小地图上的路线",
	["El camino hasta el destino dibujado en el mapa."] = "在地图上画出前往目的地的路线。",
	["El camino más sencillo para subir: un arma grande, golpes que hacen sangrar y Golpe mortal al nivel 40. Aguantas bien y matas rápido."] = "最简单的升级路线：一把大武器、造成流血的攻击，40 级获得致死打击。耐打又杀得快。",
	["El camino que baja de la sierra hacia Los Baldíos está lleno de arañas. ¡Brrr!"] = "从山上下到贫瘠之地的路上到处是蜘蛛。呜！",
	["El chat"] = "聊天",
	["El chat usa la letra de Alfa (la de Ajustes > Apariencia). El tamaño se sigue cambiando en el menú de la pestaña."] = "聊天使用 Alfa 的字体（设置 > 外观中的那个）。字号仍在标签页的菜单中更改。",
	["El clan"] = "我们的公会",
	["El clan Lobo Gélido monta lobos de verdad. Por eso es mi clan favorito, no lo voy a negar."] = "霜狼氏族骑的是真正的狼。所以那是我最喜欢的氏族，我不否认。",
	["El clan Lobo Gélido vive exiliado en el valle de Alterac. Thrall, hijo de su antiguo jefe, los encontró ahí después de escapar de Durnholde."] = "霜狼氏族流亡在奥特兰克山谷。萨尔是他们前任酋长的儿子，从敦霍尔德逃出后在那里找到了他们。",
	["El clic derecho solo sigue alejando el mapa del juego, como siempre."] = "单纯右键仍然会像往常一样缩小游戏地图。",
	["El clic izquierdo solo selecciona"] = "左键只用于选中",
	["El clásico para pelear contra jugadores: Golpe mortal corta las curas del rival, Seccionar mejorado lo deja quieto y Cargar mejorado te da ira para empezar."] = "PvP 的经典配置：致死打击削弱对手受到的治疗，强化断筋让他动弹不得，强化冲锋给你开场的怒气。",
	["El color de mi clase"] = "我的职业颜色",
	["El comerciante no lo compra"] = "商人不收购",
	["El contenido va en una columna centrada y se acomoda solo si cambias la resolución o la escala."] = "内容显示在居中的一栏中，改变分辨率或界面缩放时会自动调整。",
	["El corcho quedó lejos · relanza con %s"] = "鱼漂落得太远 · 按 %s 重新抛竿",
	["El corcho quedó lejos · vuelve a lanzar"] = "鱼漂落得太远 · 重新抛竿",
	["El cuadro del jugador al pasar el ratón. En combate no sale, para no estorbar."] = "鼠标悬停时显示玩家的鼠标提示。战斗中不显示，以免碍事。",
	["El cártel Bonvapor controla Bahía del Botín, Trinquete, Gadgetzan y Vista Eterna. Por eso esos puertos reciben a todos."] = "热砂港掌控着藏宝海湾、棘齿城、加基森和永望镇。所以这些港口欢迎所有人。",
	["El daño por segundo de tu arma a distancia."] = "你的远程武器的每秒伤害。",
	["El daño por segundo del arma: para el guerrero, lo que más cuenta al subir."] = "武器的每秒伤害：对战士来说，这是升级时最重要的。",
	["El de tu juego"] = "游戏本身的",
	["El demosaurio es el gran depredador del cráter: si oyes pasos que retumban, escóndete."] = "魔暴龙是火山口里最凶猛的掠食者：如果听到轰隆隆的脚步声，赶快躲起来。",
	["El destino de la flecha y sus zonas en el minimapa."] = "在小地图上显示箭头的目的地及其区域。",
	["El destino de la flecha, su camino y las otras metas del paso, en el mapa."] = "在地图上显示箭头的目的地、路线和该步骤的其他目标。",
	["El diario de mazmorras del motor está apagado (Ajustes > Descubrir > Mazmorras)."] = "引擎的地下城手册已关闭（设置 > 发现 > 地下城）。",
	["El diario de mazmorras está apagado"] = "地下城手册已关闭",
	["El dragón azul Azuregos ronda Azshara, cuidando la magia antigua que quedó en sus ruinas."] = "蓝龙艾索雷葛斯在艾萨拉游荡，守护着遗迹中残存的古老魔法。",
	["El druida hace de todo: puedes tanquear, curar o pegar según lo que pida el grupo."] = "德鲁伊什么都能做：可以根据队伍的需要坦克、治疗或输出。",
	["El emperador Dagran Thaurissan gobierna la Ciudad de Hierro Negro, en las Profundidades de Roca Negra."] = "达格兰·索瑞森大帝统治着黑石深渊里的黑铁之城。",
	["El enemigo esquivó: Abrumar no se puede esquivar y pega fuerte."] = "敌人躲闪了：压制无法被躲闪，而且伤害很高。",
	["El enemigo esquivó: este golpe cuerpo a cuerpo está listo."] = "敌人躲闪了：这个近战攻击已就绪。",
	["El enemigo esquivó: este golpe está listo."] = "敌人躲闪了：这个攻击已就绪。",
	["El enemigo está encima: golpéalo cuerpo a cuerpo."] = "敌人贴身了：用近战攻击它。",
	["El enemigo está lanzando un hechizo: Choque de tierra lo corta."] = "敌人正在施法：地震术可以打断它。",
	["El enemigo está lanzando un hechizo: aturdirlo lo corta."] = "敌人正在施法：击晕它就能打断。",
	["El enemigo está lanzando un hechizo: córtalo con tu escudo."] = "敌人正在施法：用你的盾牌打断它。",
	["El enemigo está lanzando un hechizo: córtalo."] = "敌人正在施法：打断它。",
	["El enemigo está lanzando un hechizo: el golpe lo corta."] = "敌人正在施法：这一击可以打断它。",
	["El enemigo está por caer: drénale el alma y gana un fragmento."] = "敌人快倒下了：吸取它的灵魂，获得一个碎片。",
	["El entrenador de oficio más cercano"] = "最近的专业训练师",
	["El espíritu te devuelve maná rápido: descansas muy poco."] = "精神让你快速恢复法力值：几乎不用休息。",
	["El estilo del mapa (terreno como el minimapa, o el arte clásico) y las opciones de Mundo."] = "地图风格（像小地图一样的地形，或经典手绘）以及世界的选项。",
	["El estilo que elegiste también puede vestir el chat, el minimapa, las barras de abajo y el mapa. Se apaga cuando quieras y todo vuelve a como estaba."] = "你选择的风格也可以用在聊天、小地图、底部的栏和地图上。随时可以关闭，一切都会恢复原样。",
	["El final"] = "结局",
	["El final de cada misión"] = "每个任务的结局",
	["El final lo verás al entregarla."] = "交付任务时你就会看到结局。",
	["El fondo se ve deformado a través del agua."] = "透过水面看，水底会变形扭曲。",
	["El fuego pega a todos los de cerca: mantén la vida alta de quienes pelean cuerpo a cuerpo."] = "火焰会伤到附近所有人：保持近战玩家的血量充足。",
	["El general Drakkisath guarda la entrada a la Guarida Alanegra, en lo alto de la Cumbre de Roca Negra."] = "达基萨斯将军守卫着黑石塔上层通往黑翼之巢的入口。",
	["El gran cruzado de la Cruzada Escarlata, Saidan Dathrohan, es en realidad el demonio Balnazzar. Lo encuentras en Stratholme."] = "血色十字军的大十字军战士达索汉其实是恶魔巴纳扎尔。你可以在斯坦索姆找到他。",
	["El guerrero que más daño hace en mazmorras. Con un tanque delante, tus dos armas no paran, y Ejecutar mejorado remata a los jefes."] = "在地下城中输出最高的战士。有坦克在前面顶着，你的双武器就能打个不停，强化斩杀负责收掉首领。",
	["El hacha de Grom Grito Infernal tiene nombre propio, y dicen que aúlla cuando corta el aire. ¡Aullar es cosa seria!"] = "格罗姆·地狱咆哮的斧头有自己的名字，据说它劈开空气时会发出嚎叫。嚎叫可是很严肃的事！",
	["El hierro negro solo se funde en la Forja Negra de las Profundidades de Roca Negra."] = "黑铁只能在黑石深渊的黑熔炉中熔炼。",
	["El hijo de Cairne, Baine, cuida el poblado Pezuña de Sangre en Mulgore."] = "凯恩的儿子贝恩在莫高雷照看血蹄村。",
	["El idioma, el estilo, lo que Alfa hace sola por ti y La Jauría, con «Cambiar» en cada cosa. También con /alfa bienvenida."] = "语言、风格、Alfa 替你自动做的事以及 La Jauría，每一项都有“更改”。也可以用 /alfa bienvenida。",
	["El izquierdo selecciona y el derecho abre el menú."] = "左键选中，右键打开菜单。",
	["El izquierdo selecciona y el derecho abre el menú. Tus buffs para otros se suman aquí al aprenderlos."] = "左键选中，右键打开菜单。你给别人的增益效果学会后会加到这里。",
	["El izquierdo selecciona y el derecho abre el menú. Tú eliges el resto."] = "左键选中，右键打开菜单。其余由你来定。",
	["El izquierdo selecciona y el derecho abre el menú: lo básico, porque tu clase no lanza hechizos sobre sus compañeros."] = "左键选中，右键打开菜单：只有基础设置，因为你的职业不会对队友施放法术。",
	["El juego elige entre estas según la situación; el ícono te muestra cuál conviene ahora."] = "游戏会根据情况在这些技能中选择；图标会显示现在最适合的那个。",
	["El juego la hizo brillar: es buen momento para usarla."] = "游戏让它发光了：现在正是使用的好时机。",
	["El juego manda la imagen en HDR."] = "游戏以 HDR 输出画面。",
	["El juego no aceptó el lote."] = "游戏没有接受这一批。",
	["El juego no aceptó esa tecla."] = "游戏不接受这个按键。",
	["El juego no aceptó la prueba."] = "游戏没有接受这次测试。",
	["El juego no da tu posición aquí (en una instancia, por ejemplo)."] = "游戏在这里不提供你的位置（例如在副本中）。",
	["El juego no deja cambiar talentos ahora mismo"] = "游戏现在不允许更改天赋",
	["El juego no deja cocinar desde aquí."] = "游戏不允许从这里烹饪。",
	["El juego no deja enviar mensajes en este momento (un encuentro o una partida). Tu rastro vuelve a salir solo cuando termine."] = "游戏现在不允许发送消息（首领战或比赛中）。结束后你的踪迹会自动恢复发送。",
	["El juego no deja que las cuentas de prueba envíen mensajes de addon ni usen canales propios. Tu grupo sí se ve."] = "游戏不允许试玩账号发送插件消息或使用自定义频道。你的队伍仍然可见。",
	["El juego no dejó cambiar las demás."] = "游戏不允许更改其余选项。",
	["El juego no dejó compartir el marcador ahora. Prueba en un momento."] = "游戏现在不允许分享标记。请稍后再试。",
	["El juego no dejó comprar ese rango."] = "游戏不允许点出这一级。",
	["El juego no dejó entrar al canal oculto de Alfa y, sin hermandad, no hay otro camino para compartir. Alfa lo vuelve a intentar sola en unos minutos. Tu grupo sí se ve."] = "游戏不允许进入 Alfa 的隐藏频道，而没有公会就没有其他共享方式。Alfa 会在几分钟后自动重试。你的队伍仍然可见。",
	["El juego no dice si la tienes"] = "游戏没有告知你是否拥有",
	["El juego no dio tus puntos todavía: se ven desde que ganas el primero."] = "游戏还没有给出你的点数：获得第一点后就能看到。",
	["El juego no la ofrece ahora mismo."] = "游戏现在没有提供它。",
	["El juego no lo dice ahora."] = "游戏目前没有提供此信息。",
	["El juego no permite usar el medidor ahora."] = "游戏现在不允许使用伤害统计。",
	["El juego no trae la ayuda de Blizzard, así que Alfa sugiere con su prioridad para %s, leyendo solo tu personaje: tu recurso, tus efectos y lo que el juego te deja usar. Con 3 o más enemigos cambia a las de área. Tú decides qué presionar."] = "游戏没有暴雪的战斗辅助，所以 Alfa 按它为%s制定的优先级给出建议，只读取你的角色：你的资源、你身上的效果以及游戏允许你使用的技能。3 个或更多敌人时会改用范围技能。按什么由你决定。",
	["El juego oculta los números exactos mientras peleas: la barra y la cifra se ven, el detalle al salir de combate."] = "战斗中游戏会隐藏精确数字：可以看到条和数值，详细信息在脱离战斗后显示。",
	["El juego rechazó confirmar los cambios. Se deshicieron para que tu árbol quede como estaba."] = "游戏拒绝确认这些更改。已撤销更改，你的天赋树保持原样。",
	["El juego solo deja cambiarla fuera de combate."] = "游戏只允许在非战斗状态下更改它。",
	["El juego todavía no carga tu árbol"] = "游戏还没有载入你的天赋树",
	["El juego todavía no carga tu árbol."] = "游戏还没有载入你的天赋树。",
	["El juego todavía no cargó tus talentos. Espera unos segundos o abre la ventana de talentos (tecla N) una vez."] = "游戏还没有载入你的天赋。请等几秒钟，或打开一次天赋窗口（N 键）。",
	["El juego todavía no dio la lista de retos: ábrelo con la tecla Y."] = "游戏还没有给出挑战列表：按 Y 键打开它。",
	["El juego todavía no la abre: se abre con tu primer punto del Legado (casi siempre, al llegar a nivel 25)."] = "游戏还没有开放它：获得第一点传承点数后开启（通常在达到 25 级时）。",
	["El juego todavía no tiene los datos de algunos objetos. En un momento aparecen."] = "游戏还没有某些物品的数据。稍后就会显示。",
	["El juego todavía oculta los números o los nombres (pasa en combate y dentro de mazmorras). Inténtalo al salir."] = "游戏仍在隐藏数字或名字（战斗中和地下城内会这样）。离开后再试。",
	["El lago Lordamere separa el Bosque de Argénteos de las Laderas de Trabalomas y de las Montañas de Alterac."] = "洛丹米尔湖把银松森林与希尔斯布莱德丘陵和奥特兰克山脉隔开。",
	["El lago de Loch Modan existe gracias a una enorme presa enana. Si se rompiera, el agua arrasaría las tierras de abajo."] = "洛克莫丹的湖泊靠一座巨大的矮人水坝才得以存在。要是水坝崩塌，洪水会冲毁下游的土地。",
	["El lago del Claro de la Luna se llama Elune'ara, en honor a la diosa de la luna."] = "月光林地的湖叫做艾露恩艾拉湖，以纪念月亮女神。",
	["El lago helado de Kel'Theril guarda ruinas de los Altonato."] = "冰封的凯斯利尔湖保存着上层精灵的遗迹。",
	["El maestro de vuelo, la posada, reparar, el banco y más, con la flecha."] = "飞行管理员、旅店、修理、银行等，箭头带你去。",
	["El maestro de vuelo, la posada, reparar, el banco y más: el más cercano, con la flecha y la ruta."] = "飞行管理员、旅店、修理、银行等：最近的那个，附箭头和路线。",
	["El maestro de vuelo, la posada, reparar, el banco... el más cercano (/alfa cerca ayuda)."] = "飞行管理员、旅店、修理、银行……最近的那个（/alfa cerca ayuda）。",
	["El mago Rhonin y el dragón Korialstrasz ayudaron a liberar a Alexstrasza en Grim Batol, y ahí quedó destruida el Alma de Demonio."] = "法师罗宁和巨龙克拉苏斯帮助在格瑞姆巴托解救了阿莱克丝塔萨，恶魔之魂也在那里被摧毁。",
	["El mago que más daño hace: hechizos de fuego y críticos que queman."] = "输出最高的法师：火焰法术和带灼烧的暴击。",
	["El mapa a tu gusto"] = "随心定制地图",
	["El mapa abre sin errores con M y se arrastra suave, aunque empieces encima de un ícono."] = "按 M 打开地图不再出错，拖动也很顺滑，即使从图标上开始拖也一样。",
	["El mapa de Alfa"] = "Alfa 地图",
	["El mapa de Alfa muestra el terreno real, con puntos de vuelo, mazmorras, barcos, zepelines y portales."] = "Alfa 的地图显示真实地形，并标出飞行点、地下城、船只、飞艇和传送门。",
	["El mapa de Alfa, el del juego y el minimapa. Si algo te estorba, apágalo aquí; los otros módulos de Alfa agregan sus capas a esta misma lista."] = "Alfa 地图、游戏地图和小地图。如果有什么碍事，就在这里关闭；Alfa 的其他模块也会把它们的图层加入这个列表。",
	["El mapa del mundo entero con zoom, tus marcadores y un solo control para todo lo que se pinta."] = "可缩放的整个世界地图、你的标记，以及统一控制地图上所有内容的开关。",
	["El mapa no se abre en combate."] = "战斗中无法打开地图。",
	["El mapa se ve más limpio: sin líneas finas entre sus pedazos ni halos oscuros en las orillas de las zonas."] = "地图更干净了：拼块之间不再有细线，区域边缘也不再有暗色光晕。",
	["El mar paga"] = "大海有回报",
	["El marco de las barras de experiencia y reputación; el relleno conserva sus colores."] = "经验条和声望条的边框；填充部分保留原来的颜色。",
	["El marco del menú del juego y de las bolsas, abajo a la derecha."] = "右下角游戏菜单和背包的边框。",
	["El mariscal Dughan cuida Villadorada y siempre anda buscando quien le eche la mano con los problemas de Elwynn."] = "治安官杜汉守护着闪金镇，总在找人帮忙解决艾尔文森林的麻烦。",
	["El medallón bajo cada marca del mapa y del minimapa: el de Alfa o solo el símbolo, sin medallón."] = "地图和小地图上每个标记下方的徽章：Alfa 的样式，或只显示图形、不带徽章。",
	["El medidor de daño aguanta en combate y la ayuda de rotación ya no te pide interrumpir lo que no se puede."] = "伤害统计在战斗中不再出问题，输出循环助手也不再要你打断无法打断的东西。",
	["El medidor no está disponible"] = "伤害统计不可用",
	["El mejor que tengas"] = "你最好的那个",
	["El mekigeniero Termochufe, el traidor de Gnomeregan, sigue escondido dentro de la ciudad: es su último jefe."] = "诺莫瑞根的叛徒麦克尼尔·瑟玛普拉格仍躲在城里：他是那里的最终首领。",
	["El menú de la lupa del mapa del juego tiene también todas las capas de Alfa."] = "游戏地图的放大镜菜单中也会列出所有 Alfa 图层。",
	["El mineral se funde en barras en cualquier forja."] = "矿石可以在任何熔炉熔炼成锭。",
	["El minimapa"] = "小地图",
	["El minimapa pasa de redondo a cuadrado, con un borde fino. No se recomienda junto con girar el minimapa."] = "小地图由圆形变为方形，带细边框。不建议与旋转小地图同时使用。",
	["El mismo arreglo llegó a los asistentes de Ruta y de Curación."] = "同样的修正也用在了路线和治疗助手上。",
	["El mitril abunda en las Tierras Inhóspitas, las Tierras del Interior y Tanaris."] = "荒芜之地、辛特兰和塔纳利斯有大量秘银。",
	["El modelo no lleva nada aquí."] = "模型这个栏位没有装备。",
	["El modo pesca se abre al salir de combate."] = "脱离战斗后会打开钓鱼模式。",
	["El modo prueba se usa fuera de combate."] = "测试模式只能在非战斗状态下使用。",
	["El motor no aceptó la guía."] = "引擎不接受这个指南。",
	["El motor no puede armar guías ahora."] = "引擎现在无法生成指南。",
	["El mundo entero en un mapa"] = "整个世界尽在一张地图",
	["El mundo pierde el color mientras eres espíritu."] = "你处于灵魂状态时，世界会失去色彩。",
	["El más cercano cuando le toque, por tiempo de camino."] = "轮到它时按路程时间选最近的。",
	["El más cercano, por tiempo de camino"] = "最近的，按路程时间",
	["El más cercano: %s"] = "最近的：%s",
	["El módulo Curación no está cargado."] = "“治疗”模块未加载。",
	["El nombre de cada zona sobre el mapa de Alfa."] = "在 Alfa 地图上显示每个区域的名称。",
	["El número abajo a la izquierda de cada pieza de equipo."] = "显示在每件装备左下角的数字。",
	["El número es el orden en que se toma. Pasa el ratón por un talento para ver qué hace."] = "数字是点天赋的顺序。鼠标指向天赋可查看效果。",
	["El número que cuenta hacia atrás. Apagado, solo la barra."] = "倒计时数字。关闭时只显示进度条。",
	["El objeto"] = "物品",
	["El objeto que usa el paso actual, o el objeto de misión que junta, brilla en tus bolsas. Un objeto que necesita un paso más adelante lleva un candado, para que no lo vendas."] = "当前步骤要使用的物品，或要收集的任务物品，会在背包中发光。后续步骤需要的物品会显示锁标记，以免误卖。",
	["El orden importa más que los números: busca piezas con las primeras de la lista."] = "顺序比数值更重要：优先找带有列表前几项属性的装备。",
	["El paisaje lejano deja de perderse en la niebla espesa."] = "远处的风景不再消失在浓雾中。",
	["El paisaje lejano deja de perderse en la niebla espesa. A veces se nota dónde termina lo que está cargado."] = "远处的风景不再消失在浓雾中。有时能看出已加载区域的边界。",
	["El paquete de datos de Alfa (Alfa_Codex) está desactivado: actívalo en la lista de addons y recarga."] = "Alfa 的数据包（Alfa_Codex）已停用：请在插件列表中启用并重载。",
	["El paso de ahora de tu guía te lleva a entrenar."] = "你指南的当前步骤会带你去训练。",
	["El pequeño rey Anduin Wrynn lleva su nombre en honor a Anduin Lothar, el héroe que salvó a su pueblo."] = "年幼的国王安度因·乌瑞恩以安度因·洛萨命名，以纪念这位拯救了他人民的英雄。",
	["El primer clic abre la Cocina del juego; el siguiente cocina el lote. Tienes que estar junto a un fuego."] = "第一次点击打开游戏的烹饪窗口；下一次点击烹饪这一批。你必须在火堆旁边。",
	["El primer jefe de guerra de la Horda fue Mano Negra. Su hijo Rend Mano Negra hoy sirve a Nefarian en la Cumbre de Roca Negra."] = "部落的第一位酋长是黑手。他的儿子雷德·黑手如今在黑石塔为奈法利安效力。",
	["El primer punto del Legado suele llegar al nivel 25, y con él se abre el Legado."] = "第一点传承点数通常在 25 级获得，传承也随之开启。",
	["El próximo: %s"] = "下一个：%s",
	["El pícaro más fácil para subir: pega de frente, esquiva mucho y aguanta mejor que los demás."] = "最容易升级的潜行者：正面输出、躲闪多，比其他天赋更耐打。",
	["El rango Experto viene en un libro que vende el pescador de Bahía del Botín, en Tuercespina."] = "高级钓鱼要靠一本书来学，由荆棘谷藏宝海湾的渔夫出售。",
	["El rango de niveles de cada zona, con color según tu nivel."] = "每个区域的等级范围，按你的等级着色。",
	["El rastreador te dice el siguiente paso y la flecha te lleva."] = "追踪器会告诉你下一步，箭头会带你过去。",
	["El registro de daño del juego está apagado"] = "游戏的伤害记录已关闭",
	["El registro de daño del juego está apagado: enciéndelo para ver el top de tu grupo."] = "游戏的伤害记录已关闭：开启后即可查看你队伍的排行。",
	["El registro del Legado"] = "传承奖励进度",
	["El reino humano de Alterac traicionó a la Alianza en la Segunda Guerra: su rey, Aiden Perenolde, se alió con la Horda. Por eso el reino desapareció."] = "人类王国奥特兰克在第二次战争中背叛了联盟：国王艾登·佩雷诺德投靠了部落。王国因此灭亡。",
	["El reino limita los mensajes de addon salientes: %s"] = "服务器限制了发出的插件消息：%s",
	["El rey Llane Wrynn murió en la Primera Guerra a manos de Garona, la espía de la Horda."] = "莱恩·乌瑞恩国王在第一次战争中死于部落间谍迦罗娜之手。",
	["El rey Magni Barbabronce gobierna Forjaz; sus hermanos son Muradin y Brann, el explorador."] = "国王麦格尼·铜须统治着铁炉堡；他的兄弟是穆拉丁和探险家布莱恩。",
	["El rey Thoradin unió a las tribus humanas en Arathor, y los altos elfos les enseñaron magia para vencer juntos a los trols Amani."] = "索拉丁国王在阿拉索统一了人类部族，高等精灵教会他们魔法，一起击败了阿曼尼巨魔。",
	["El rey Varian Wrynn es hijo de Llane, el rey que murió en la Primera Guerra."] = "瓦里安·乌瑞恩国王是莱恩之子，莱恩就是在第一次战争中丧生的那位国王。",
	["El rey Varian desapareció camino a una reunión de paz. Mientras tanto reina su hijo Anduin, todavía niño, con el alto señor Bolvar Fordragón como regente."] = "瓦里安国王在前往和平会议的途中失踪了。在此期间，由他年幼的儿子安度因即位，大领主伯瓦尔·弗塔根担任摄政王。",
	["El sanador de los chamanes: curas en cadena y tótems que ayudan a todo el grupo."] = "萨满祭司的治疗天赋：治疗链，以及帮助全队的图腾。",
	["El sanador de los druidas: curas a cualquier grupo y sobrevives bien, aunque en solitario matas lento."] = "德鲁伊的治疗天赋：能治好任何队伍，生存能力也不错，不过单人杀怪较慢。",
	["El sanador de los paladines: curas fuertes y mucha armadura, ideal para grupos."] = "圣骑士的治疗天赋：治疗量大、护甲高，非常适合组队。",
	["El sanador puro: curas grandes y curas para todo el grupo."] = "纯粹的治疗者：大量单体治疗和群体治疗。",
	["El servicio"] = "服务",
	["El sistema de equipo de Alfa no está disponible."] = "Alfa 的装备系统不可用。",
	["El sol aquí no perdona: las Tierras Inhóspitas son tierra de coyotes, buitres y basiliscos."] = "这里的太阳毫不留情：荒芜之地是土狼、秃鹫和蜥蜴的天下。",
	["El suelo y los muros se ven nítidos aunque estén lejos o de lado."] = "即使在远处或斜着看，地面和墙壁也很清晰。",
	["El talento que toca"] = "该点的天赋",
	["El tanque clásico: bloqueas mucho, generas amenaza con Revancha y Embate con escudo, y tienes Último recurso para cuando todo sale mal."] = "经典坦克：大量格挡，用复仇和盾牌猛击制造威胁，出问题时还有破釜沉舟。",
	["El tanque más difícil de matar: todos los talentos de defensa, Muro de escudo mejorado y Último recurso pronto. Perfecto para empezar a tanquear."] = "最难被打死的坦克：所有防御天赋、强化盾墙，并尽早点出破釜沉舟。最适合新手坦克入门。",
	["El terreno real en el mapa"] = "地图上的真实地形",
	["El texto es demasiado largo."] = "文字太长了。",
	["El texto llegó cortado o cambiado: cópialo otra vez."] = "文字不完整或被改动了：请重新复制。",
	["El tipo de nodos que une la ruta."] = "路线所连接的采集点类型。",
	["El tono de los fondos: Grafito es el de Alfa, Noche el más oscuro y Pizarra un gris neutro."] = "背景的色调：石墨是 Alfa 的默认色调，夜晚最暗，石板为中性灰。",
	["El top de DPS de tu grupo o banda en una ventana pequeña, con la pelea actual y la anterior."] = "在一个小窗口中显示你小队或团队的 DPS 排行，包括当前和上一场战斗。",
	["El torio abunda en el Cráter de Un'Goro y en Cuna del Invierno."] = "安戈洛环形山和冬泉谷有大量瑟银。",
	["El velo de pantalla de algunas zonas y hechizos de las sombras."] = "某些区域和暗影法术的屏幕笼罩效果。",
	["El vendedor más cercano"] = "最近的商人",
	["El verdadero nombre de Thrall es Go'el, el que le dieron sus padres."] = "萨尔的真名是古伊尔，那是他父母给他取的名字。",
	["El viejo ermitaño Abercrombie parece amable... hasta que descubres a quién intenta revivir."] = "老隐士亚伯克隆比看起来很和善……直到你发现他想复活的是谁。",
	["El «zug zug» de los peones quiere decir algo así como «de acuerdo». ¡Zug zug, jefe!"] = "苦工说的“zug zug”大概是“好的”的意思。zug zug，老大！",
	["El árbol de ruta de Alfa, misiones que se liberan y un catálogo de objetos."] = "Alfa 的路线树、陆续解锁的任务，以及物品目录。",
	["El ícono grande es lo que conviene presionar ahora y los pequeños, lo que sigue. Si late, el juego activó esa habilidad; el barrido oscuro es su recarga. Tú decides: Alfa nunca aprieta nada."] = "大图标是现在最该按的，小图标是接下来的。如果它在跳动，表示游戏点亮了该技能；深色转圈是它的冷却。由你决定：Alfa 绝不会替你按任何键。",
	["El último punto: paras un poco más."] = "最后一点：招架再多一点。",
	["Elegida por ti en los ajustes."] = "由你在设置中选择。",
	["Elegida por tus talentos."] = "由你的天赋决定。",
	["Elegido"] = "已选择",
	["Elegido por ti"] = "你自选的",
	["Elegir capas"] = "选择图层",
	["Elegir la siguiente guía"] = "选择下一个指南",
	["Elegir lo que pide tu paso"] = "选择你的步骤所需的选项",
	["Elegir mi camino"] = "选择我的方向",
	["Elegir mi primera guía"] = "选择我的第一个指南",
	["Elegir mi tecla"] = "选择我的按键",
	["Elegir otra guía"] = "选择其他指南",
	["Elegir para copiar"] = "选择以复制",
	["Elegir qué sigue"] = "选择接下来做什么",
	["Elegir todo"] = "全选",
	["Elegir una guía"] = "选择指南",
	["Elegir una guía por ti"] = "替你选择指南",
	["Elegiste: %s"] = "已选择：%s",
	["Elemental"] = "元素",
	["Elemental para subir"] = "元素（升级）",
	["Elfos de la noche"] = "暗夜精灵",
	["Elige abajo qué cocinar y cuánto: la cola espera tu clic para cada lote."] = "在下方选择要烹饪什么、烹饪多少：队列会等你点击每一批。",
	["Elige algo de la lista"] = "从列表中选择一项",
	["Elige el objeto"] = "选择物品",
	["Elige el objeto en la Enciclopedia."] = "在百科中选择物品。",
	["Elige la opción que nombra tu guía, o abre la tienda o el entrenamiento que necesitas."] = "选择指南指定的选项，或打开你需要的商店或训练。",
	["Elige qué guardar: lo que ya tienes en el banco, los materiales, una categoría o todo lo que no sea equipo. Se mueve de una vez, fuera de combate."] = "选择要存放的东西：银行里已有的物品、材料、某个类别，或所有非装备物品。脱离战斗时一次性移动。",
	["Elige qué quieres hacer y Alfa te lleva paso a paso."] = "选择你想做的事，Alfa 会一步步带你。",
	["Elige qué se ve en el mapa: guía, misiones, raros, viajes, zonas y lo que agregan otros módulos."] = "选择地图上显示的内容：指南、任务、稀有、旅行、区域以及其他模块添加的内容。",
	["Elige sola la única opción de los PNJ sin misiones."] = "对没有任务的 NPC，自动选择其唯一的选项。",
	["Elige solo misiones que ya puedes tomar."] = "只选择你现在就能接的任务。",
	["Elige tu camino. Si no sabes, empieza por subir de nivel: Alfa te dice qué conviene."] = "选择你的方向。如果不确定，就从升级开始：Alfa 会告诉你怎么做最划算。",
	["Elige tu estilo"] = "选择你的风格",
	["Elige tu tecla para pescar"] = "选择你的钓鱼按键",
	["Elige tus clics"] = "选择你的点击",
	["Elige tus clics, acomoda tus marcos y pruébalos. Te toma un minuto."] = "选择你的点击、摆放框体并测试。只需一分钟。",
	["Elige tú la zona."] = "由你选择区域。",
	["Elige un camino: Alfa arma tu plan y te guía paso a paso."] = "选择一条路线：Alfa 会制定你的计划并一步步带你。",
	["Elige un marcador."] = "选择一个标记。",
	["Elige un servicio."] = "选择一项服务。",
	["Elige una captura"] = "选择一种渔获",
	["Elige una guía para empezar"] = "选择一个指南开始",
	["Elige una mazmorra."] = "选择一个地下城。",
	["Elige una misión"] = "选择一个任务",
	["Elige una profesión"] = "选择一项专业",
	["Elige una profesión."] = "选择一项专业。",
	["Elige uno y lo ves al instante en esta ventana y en todas las de Alfa, también la flecha."] = "选择一个，就能立即在此窗口和 Alfa 的所有窗口中看到效果，箭头也一样。",
	["Eliges una"] = "任选一个",
	["Ella duerme a todo el grupo y luego resucita a Mograine: es normal, no se asusten."] = "她会让整个队伍睡着，然后复活莫格莱尼：这是正常的，别慌。",
	["Elune, la diosa de la luna, es la fe de los elfos de la noche. Sus sacerdotisas son las Hermanas de Elune, y Tyrande es su suma sacerdotisa."] = "月亮女神艾露恩是暗夜精灵的信仰。她的女祭司们组成艾露恩姐妹会，泰兰德是她们的大祭司。",
	["Embate con escudo: mucho daño y amenaza."] = "盾牌猛击：高伤害和高威胁。",
	["Embate deja de reiniciar tu ataque: un golpe extra entre golpe y golpe."] = "猛击不再重置你的攻击计时：在两次普通攻击之间多打一下。",
	["Embate sin perder tu ataque automático."] = "使用猛击不丢失自动攻击。",
	["Embate sin perder tu ataque."] = "使用猛击不打乱攻击节奏。",
	["Embate sin perder tu golpe automático."] = "使用猛击不丢失自动攻击。",
	["Embate sin reiniciar tu ataque: un golpe extra."] = "猛击不重置攻击计时：多打一下。",
	["Embate: un golpe fuerte entre golpe y golpe."] = "猛击：在两次攻击之间打出一记重击。",
	["Empezar"] = "开始",
	["Empezar de cero"] = "从零开始",
	["Empezar de nuevo"] = "重新开始",
	["Empezar otra"] = "再开始一次",
	["Empezar otra sesión"] = "开始新的钓鱼记录",
	["Empezó %s"] = "开始于%s",
	["Empezó %s."] = "开始于%s。",
	["Empieza al usar este objeto"] = "使用此物品后开始",
	["Empieza aquí"] = "从这里开始",
	["Empieza con %s, que se consigue en la mazmorra."] = "从%s开始，可在地下城中获得。",
	["Empieza con %s, que suelta %s."] = "从%s开始，由%s掉落。",
	["Empieza con tu hechizo más lento desde lejos y termina con los instantáneos."] = "从远处用施法时间最长的法术开怪，再用瞬发法术收尾。",
	["Empieza dentro"] = "在副本内开始",
	["Empieza una misión"] = "开始一个任务",
	["Empiezas: nivel %d"] = "起始：%d 级",
	["En %s"] = "在%s",
	["En 9 idiomas"] = "支持 9 种语言",
	["En Burning Crusade, Karazhan abre sus puertas como banda."] = "到了燃烧的远征，卡拉赞会作为团队副本开放。",
	["En Burning Crusade, el Vuelo Bronce pide ayuda en las Cavernas del Tiempo contra dragones que quieren cambiar la historia."] = "到了燃烧的远征，青铜龙军团会在时光之穴求助，对抗企图改变历史的巨龙。",
	["En Burning Crusade, las Cavernas del Tiempo te regresan a estas laderas para ver la huida de Thrall de Durnholde."] = "到了燃烧的远征，时光之穴会把你送回这片丘陵，见证萨尔从敦霍尔德逃脱。",
	["En Caer Darrow, junto al lago, todavía rondan los fantasmas de sus antiguos vecinos."] = "在湖边的凯尔达隆，昔日居民的鬼魂仍在游荡。",
	["En Ciudad Manitas, dentro de Forjaz, viven los gnomos que escaparon de Gnomeregan."] = "铁炉堡里的侏儒区住着从诺莫瑞根逃出来的侏儒。",
	["En Costa Oscura la Liga de Expedicionarios desentierra fósiles gigantes."] = "探险者协会正在黑海岸挖掘巨大的化石。",
	["En Costa Oscura viven lechúcicos, criaturas mitad búho y mitad oso que veneran la luna."] = "黑海岸住着枭兽，这种半枭半熊的生物崇拜月亮。",
	["En Desolace está el cementerio de los kodos, donde los viejos kodos van a morir."] = "凄凉之地有科多兽坟场，年老的科多兽会去那里等待死亡。",
	["En Durotar ya te topas con el Filo Ardiente, un culto de brujos orcos que sigue adorando a los demonios."] = "在杜隆塔尔你就会遇到火刃，一个仍在崇拜恶魔的兽人术士邪教。",
	["En Elwynn, una señora vende gatitos de compañía. ¡Yo me llevo bien con los gatos... casi siempre!"] = "艾尔文森林有位女士在卖小猫宠物。我跟猫处得很好……大多数时候！",
	["En Entrañas venden cucarachas de mascota. Cada quien sus gustos."] = "幽暗城有卖蟑螂宠物。萝卜青菜，各有所爱。",
	["En Feralas está uno de los grandes árboles por los que los dragones verdes entran al Sueño Esmeralda."] = "菲拉斯有一棵巨树，绿龙经由它进入翡翠梦境。",
	["En Forever, Onyxia, la Cumbre Hyjal y Barrow Deeps dan retos del Legado al vencerlas."] = "在 Forever 中，击败奥妮克希亚、海加尔山和古墓深渊都会获得传承挑战。",
	["En Forever, el banco vende casillas de bolsa una tras otra: más espacio para tus tesoros."] = "在 Forever 中，银行会一格接一格地出售背包栏位：给你的宝贝更多空间。",
	["En Forever, los rangos de honor y la reputación de los campos de batalla también dan retos del Legado."] = "在 Forever 中，荣誉军衔和战场声望也会带来传承挑战。",
	["En Forever, los retos del Legado dan puntos a toda tu cuenta, y cada personaje los gasta en sus árboles. Ábrelo con la tecla Y."] = "在 Forever 中，传承挑战会给你整个账号点数，每个角色把点数花在自己的天赋树上。按 Y 键打开。",
	["En Forjaz, la sala de la Liga de Expedicionarios tiene un museo con fósiles enormes. Brann Barbabronce es su explorador más famoso."] = "在铁炉堡，探险者协会的大厅里有一座陈列巨大化石的博物馆。布莱恩·铜须是协会最有名的探险家。",
	["En Gadgetzan, el cocinero Dirge enseña una de las mejores recetas del Clásico, con carne de quimerok."] = "在加基森，厨师迪尔格教授经典版中最好的配方之一，用的是奇美拉的肉。",
	["En Jaedenar se esconde el Consejo de la Sombra, brujos que sirven a la Legión Ardiente."] = "暗影议会藏身在加德纳尔，他们是效忠燃烧军团的术士。",
	["En Jardín Noble se esconden huevos de colores por los pueblos iniciales; dentro hay dulces y a veces ropa de primavera."] = "复活节期间，新手城镇各处都藏着彩蛋；里面有糖果，有时还有春装。",
	["En Kharanos, la posada y la destilería Cebatruenos son la parada obligada para calentarse... por dentro y por fuera."] = "在卡拉诺斯，旅店和雷酒酿酒厂是取暖必去的地方……从里暖到外。",
	["En Molino Ámbar se refugian magos de Dalaran, y no les gustan nada las visitas de los Renegados."] = "达拉然的法师们躲在安伯米尔，他们一点也不欢迎被遗忘者来访。",
	["En Naxxramas, el gran Alexandros Mograine reaparece como uno de los Cuatro Jinetes de la Plaga. Qué triste destino para un héroe."] = "在纳克萨玛斯，伟大的亚历山德罗斯·莫格莱尼以天灾军团天启四骑士之一的身份重新出现。英雄落得这种下场，真令人难过。",
	["En Nethergarde, unos magos de sangre te cambian partes de las bestias de aquí por elixires que te potencian un buen rato."] = "在守望堡，几位血法师会用这里野兽的身体部位跟你换药剂，能长时间强化你。",
	["En Orgrimmar, el Valle de la Sabiduría guarda la fortaleza de Thrall, y el Valle del Honor reúne a guerreros y cazadores."] = "在奥格瑞玛，智慧谷里有萨尔的要塞，荣誉谷则聚集着战士和猎人。",
	["En Pico Nidal manda el thane Falstad Martillo Salvaje, señor de los jinetes de grifo."] = "统治鹰巢山的是领主弗斯塔德·蛮锤，狮鹫骑士的首领。",
	["En Pico Nidal viven los enanos Martillo Salvaje, famosos por volar sobre grifos."] = "蛮锤矮人住在鹰巢山，他们以骑乘狮鹫闻名。",
	["En Seradane hay uno de los grandes árboles que llevan al Sueño Esmeralda, y los dragones verdes lo custodian."] = "瑟拉丹有一棵通往翡翠梦境的巨树，由绿龙守护。",
	["En Tanaris están las Cavernas del Tiempo, donde el Vuelo Bronce de Nozdormu vigila la historia."] = "塔纳利斯有时光之穴，诺兹多姆的青铜龙军团在那里守望历史。",
	["En Tirisfal está la entrada al Monasterio Escarlata, uno de los lugares más visitados por los aventureros de nivel medio."] = "提瑞斯法林地有血色修道院的入口，那是中等级冒险者最常去的地方之一。",
	["En Uldaman están los Discos de Norgannon, registros de los titanes que cuentan cómo crearon a los terráneos, los antepasados de piedra de los enanos."] = "奥达曼里有诺甘农圆盘，这些泰坦的记录讲述了他们如何创造土灵——矮人的岩石祖先。",
	["En Vallefresno, Grom Grito Infernal mató al semidiós Cenarius cuando la Horda empezó a talar el bosque."] = "在灰谷，部落开始砍伐森林时，格罗姆·地狱咆哮杀死了半神塞纳留斯。",
	["En Vallefresno, Grom volvió a beber sangre demoníaca; Thrall lo rescató y Grom pudo redimirse antes de morir."] = "在灰谷，格罗姆再次饮下了恶魔之血；萨尔救出了他，格罗姆在死前得以自我救赎。",
	["En Ventormenta hay un barrio de enanos, uno de magos y un parque donde se reúnen los elfos de la noche."] = "暴风城有矮人区、法师区，还有一座暗夜精灵聚集的公园。",
	["En Warcraft III, si le das muchos clics a una unidad empieza a decir cosas chistosas. Yo, en cambio, te doy consejos."] = "在魔兽争霸 III 中，一直点同一个单位，它就会开始说些好笑的话。而我呢，会给你建议。",
	["En arco"] = "弧线",
	["En bancos de peces de: %s."] = "在以下鱼群中：%s。",
	["En camino"] = "前往中",
	["En cero los números suben derechos; más alto, salen disparados hacia los lados."] = "设为零时数字笔直上升；数值越高，数字越往两侧飞散。",
	["En combate"] = "战斗中",
	["En combate el juego oculta los números exactos: las barras y las cifras se ven igual, el detalle y el anuncio, al salir."] = "战斗中游戏会隐藏精确数字：条和数值照常显示，详细信息和通报在脱离战斗后才可用。",
	["En combate el mapa del juego no se abre desde Alfa: usa el de Alfa."] = "战斗中无法从 Alfa 打开游戏地图：请使用 Alfa 地图。",
	["En combate no aparece el cuadro de los personajes y criaturas del mundo (el de los marcos sí)."] = "战斗中不显示世界中角色和生物的鼠标提示（框体上的仍会显示）。",
	["En combate no hay prueba: sal de la pelea y vuelve a este paso."] = "战斗中无法测试：脱离战斗后再回到这一步。",
	["En combate no puedo buscar: inténtalo al terminar la pelea."] = "战斗中无法搜索：请在战斗结束后再试。",
	["En combate no se puede: espera a terminar."] = "战斗中无法进行：请等战斗结束。",
	["En combate · la pesca espera"] = "战斗中 · 钓鱼暂停",
	["En combate, el ícono muestra la habilidad que sugiere la ayuda de Blizzard y las %d que siguen. Tú decides qué presionar: Alfa nunca aprieta nada por ti."] = "战斗中，图标会显示暴雪战斗辅助建议的技能，以及接下来的 %d 个。按什么由你决定：Alfa 绝不会替你按任何键。",
	["En combate, el ícono muestra la habilidad que sugiere la ayuda de Blizzard. Tú decides qué presionar: Alfa nunca aprieta nada por ti."] = "战斗中，图标会显示暴雪战斗辅助建议的技能。按什么由你决定：Alfa 绝不会替你按任何键。",
	["En combate: espera a terminar"] = "战斗中：请等待战斗结束",
	["En curso"] = "进行中",
	["En el Casco Antiguo está el SI:7, los espías y pícaros al servicio del reino."] = "旧城区里有军情七处，为王国效力的间谍和盗贼都在那里。",
	["En el Clásico mandan Thrall en Orgrimmar, Cairne en Cima del Trueno, Sylvanas en Entrañas y Vol'jin con los Lanza Negra."] = "在经典版中，萨尔统治奥格瑞玛，凯恩统治雷霆崖，希尔瓦娜斯统治幽暗城，沃金领导暗矛部族。",
	["En el Clásico nadie sabe dónde anda Alamuerte; los que dan la cara son sus hijos, Onyxia y Nefarian."] = "在经典版中，没人知道死亡之翼在哪里；露面的是他的子女，奥妮克希亚和奈法利安。",
	["En el Clásico necesitas flechas o balas: lleva siempre de más en tu carcaj o tu bolsa de munición."] = "在经典版中你需要箭或子弹：箭袋或弹药袋里一定要多带一些。",
	["En el Clásico necesitas un cuchillo de desollar en tus bolsas."] = "在经典版中，你的背包里需要一把剥皮小刀。",
	["En el Clásico solo puedes tener dos profesiones principales, pero Cocina, Pesca y Primeros auxilios se aprenden aparte."] = "在经典版中，你只能学两个主要专业，但烹饪、钓鱼和急救可以另外学。",
	["En el Clásico, Costasur contra Molino Tarren era la pelea entre bandos más famosa del mundo."] = "在经典版中，南海镇对塔伦米尔是全世界最有名的阵营之战。",
	["En el Clásico, a nivel 20 aprendes a teletransportarte a las capitales, y a 40 a abrir portales para los demás."] = "在经典版中，20 级时你能学会传送到主城，40 级时能为别人开传送门。",
	["En el Clásico, a nivel 20 haces la misión de los venenos; después los mejoras con tu entrenador."] = "在经典版中，20 级时你要做毒药任务；之后可以找训练师提升毒药。",
	["En el Clásico, a nivel 40 haces la misión de tu caballo de guerra, y a 60 la cadena épica del destrero."] = "在经典版中，40 级时你要做战马的任务，60 级时则是战驹的史诗任务链。",
	["En el Clásico, a nivel 40 recibes un corcel vil, y a 60 una cadena épica en La Masacre te da uno aún más temible."] = "在经典版中，40 级时你会得到一匹地狱战马，60 级时厄运之槌的史诗任务链会给你一匹更可怕的坐骑。",
	["En el Clásico, abrir las puertas de Ahn'Qiraj pidió un esfuerzo de guerra de todo el servidor: montañas de materiales y una cadena larguísima."] = "在经典版中，开启安其拉之门需要全服务器的战争动员：堆积如山的材料和一条超长的任务链。",
	["En el Clásico, algunos peces solo pican de noche o de día."] = "在经典版中，有些鱼只在晚上或白天才会上钩。",
	["En el Clásico, cada raza de sacerdote tiene un hechizo propio. Pregúntale a tu entrenador cuál te toca."] = "在经典版中，每个种族的牧师都有自己的专属法术。问问你的训练师你的是哪一个。",
	["En el Clásico, después de vendarte queda un rato en que no puedes usar otra venda."] = "在经典版中，用过绷带后会有一段时间不能再用另一条绷带。",
	["En el Clásico, el Cetro de las Arenas Movedizas abrió las puertas de Ahn'Qiraj tras una larguísima cadena de misiones."] = "在经典版中，流沙节杖在一条超长的任务链之后开启了安其拉之门。",
	["En el Clásico, el arco épico de los cazadores sale de una cadena contra demonios que empieza en el Claro de la Luna."] = "在经典版中，猎人的史诗弓来自一条对抗恶魔的任务链，从月光林地开始。",
	["En el Clásico, el chat de Los Baldíos era famoso por sus pláticas eternas... y por preguntar dónde estaba la esposa de Mankrik."] = "在经典版中，贫瘠之地的聊天频道以没完没了的闲聊闻名……还有大家都在问曼科里克的老婆在哪里。",
	["En el Clásico, el nivel máximo es 60 y llegar lleva su tiempo. Por eso cada nivel se festeja."] = "在经典版中，等级上限是 60 级，要达到得花不少时间。所以每升一级都值得庆祝。",
	["En el Clásico, el rango de honor 14 es Gran Mariscal para la Alianza y Gran Señor de la Guerra para la Horda."] = "在经典版中，荣誉军衔 14 级在联盟是大元帅，在部落是大将军。",
	["En el Clásico, la Feria de la Luna Negra a veces se instala en Mulgore, cerca del poblado Pezuña de Sangre."] = "在经典版中，暗月马戏团有时会在莫高雷的血蹄村附近扎营。",
	["En el Clásico, la Feria de la Luna Negra a veces se instala junto a Villadorada."] = "在经典版中，暗月马戏团有时会在闪金镇旁边扎营。",
	["En el Clásico, la Horda la forman orcos, trols Lanza Negra, tauren y Renegados; la Alianza, humanos, enanos, gnomos y elfos de la noche."] = "在经典版中，部落由兽人、暗矛巨魔、牛头人和被遗忘者组成；联盟则是人类、矮人、侏儒和暗夜精灵。",
	["En el Clásico, la Plaga invadió el mundo con necrópolis flotantes antes de que se abriera Naxxramas."] = "在经典版中，纳克萨玛斯开放之前，天灾军团曾用漂浮的通灵塔入侵世界。",
	["En el Clásico, la actitud defensiva se gana con una misión al nivel 10, y la rabiosa con otra al nivel 30."] = "在经典版中，防御姿态要在 10 级做任务获得，狂暴姿态要在 30 级做另一个任务。",
	["En el Clásico, la casa de subastas de Forjaz es la más movida de toda la Alianza."] = "在经典版中，铁炉堡的拍卖行是整个联盟最热闹的。",
	["En el Clásico, la forma de oso se gana con una misión a nivel 10 y la acuática con otra a nivel 16; luego vienen la felina y la de viaje."] = "在经典版中，熊形态要在 10 级做任务获得，水栖形态在 16 级做另一个任务；之后是猎豹形态和旅行形态。",
	["En el Clásico, la montura de nivel 40 es mucho más rápida que correr, y la épica de nivel 60 todavía más."] = "在经典版中，40 级的坐骑比跑步快得多，60 级的史诗坐骑更快。",
	["En el Clásico, la tela se puede donar en tu capital a cambio de reputación."] = "在经典版中，你可以在主城捐献布料来换取声望。",
	["En el Clásico, las bandas grandes son de 40 jugadores, y Zul'Gurub y las Ruinas de Ahn'Qiraj, de 20."] = "在经典版中，大型团队副本是 40 人，祖尔格拉布和安其拉废墟是 20 人。",
	["En el Clásico, los Renegados se quitan el miedo, el encanto y el sueño con su voluntad."] = "在经典版中，被遗忘者能靠意志摆脱恐惧、魅惑和睡眠效果。",
	["En el Clásico, los domingos por la tarde Bahía del Botín organizaba un concurso de pesca: ganaba quien entregara primero cuarenta peces de una especie especial."] = "在经典版中，每周日下午藏宝海湾都会举办钓鱼大赛：最先交出四十条特殊鱼的人获胜。",
	["En el Clásico, los enanos pueden buscar tesoros con un rastreo propio. ¡Ideal para encontrar cofres!"] = "在经典版中，矮人有专属的寻找财宝技能。找宝箱最合适了！",
	["En el Clásico, los enanos se convierten en piedra para quitarse venenos y sangrados, y son buenos con las armas de fuego."] = "在经典版中，矮人能化为石头来摆脱毒药和流血效果，而且擅长使用枪械。",
	["En el Clásico, los gnomos pueden ser guerreros, pícaros, magos o brujos."] = "在经典版中，侏儒可以当战士、盗贼、法师或术士。",
	["En el Clásico, los gnomos son más listos que el resto, tienen talento para la ingeniería y se zafan de lo que los inmoviliza."] = "在经典版中，侏儒比其他种族更聪明，擅长工程学，还能挣脱定身效果。",
	["En el Clásico, los humanos ganan reputación más rápido gracias a su diplomacia, y tienen buen ojo para ver a los sigilosos."] = "在经典版中，人类凭借外交才能获得声望更快，而且善于发现潜行的敌人。",
	["En el Clásico, los maestros de armas de las capitales te enseñan a usar armas nuevas."] = "在经典版中，主城的武器大师会教你使用新武器。",
	["En el Clásico, los orcos resisten mejor los aturdimientos y sus mascotas pegan más fuerte."] = "在经典版中，兽人更能抵抗昏迷效果，他们的宠物也打得更痛。",
	["En el Clásico, los tauren tienen más vida, un pisotón que aturde a los enemigos cercanos y mano verde con las hierbas."] = "在经典版中，牛头人生命值更高，有一记能击晕附近敌人的践踏，还特别擅长采草药。",
	["En el Clásico, los trols se regeneran rápido, entran en frenesí, pegan más fuerte a las bestias y son buenos con arcos y armas arrojadizas."] = "在经典版中，巨魔恢复得快，能进入狂暴，对野兽伤害更高，而且擅长弓和投掷武器。",
	["En el Clásico, muchas comidas te dejan bien alimentado y te suben estadísticas un buen rato."] = "在经典版中，许多食物会让你进入“进食充分”状态，在一段时间内提升属性。",
	["En el Clásico, para pasar de 225 hay una misión de triaje en Theramore o en Sentencia."] = "在经典版中，要超过 225 点，需要在塞拉摩或落锤镇完成一个急救任务。",
	["En el Clásico, quienes terminaron la cadena del cetro y tocaron el gong de Ahn'Qiraj ganaron un título y una montura únicos."] = "在经典版中，完成节杖任务链并敲响安其拉之锣的人获得了独一无二的头衔和坐骑。",
	["En el Clásico, solo elfos de la noche y tauren pueden ser druidas."] = "在经典版中，只有暗夜精灵和牛头人能当德鲁伊。",
	["En el Clásico, solo humanos y enanos pueden ser paladines."] = "在经典版中，只有人类和矮人能当圣骑士。",
	["En el Clásico, solo orcos, trols y tauren pueden ser chamanes."] = "在经典版中，只有兽人、巨魔和牛头人能当萨满。",
	["En el Clásico, tu Reencarnación te revive a ti mismo, pero necesita un ankh en tus bolsas."] = "在经典版中，转生可以让你自己复活，但背包里需要有一个十字章。",
	["En el Enclave Cenarion los druidas enseñan a los suyos el camino de la naturaleza."] = "在塞纳里奥区，德鲁伊们向同伴传授自然之道。",
	["En el Festival Lunar, la gente viene al Claro de la Luna a honrar a sus ancestros."] = "春节期间，人们来到月光林地祭拜祖先。",
	["En el Festival Lunar, un emisario en las capitales te puede llevar al Claro de la Luna para celebrar con los druidas."] = "春节期间，主城的使者可以带你去月光林地和德鲁伊们一起庆祝。",
	["En el Festival de Fuego del Solsticio de Verano hay hogueras en muchos pueblos: honrar las de tu bando da premios, y apagar las del otro también."] = "仲夏火焰节期间，许多城镇都有篝火：向自己阵营的篝火致敬能获得奖励，熄灭对方的篝火也可以。",
	["En el Festival de Invierno venden bolas de nieve. ¡Lánzaselas a tus amigos, que yo las atrapo!"] = "冬幕节期间有卖雪球。扔向你的朋友吧，我来接！",
	["En el Festival de Invierno, el Gran Padre Invierno reparte regalos en Forjaz y Orgrimmar, y bajo el árbol aparecen paquetes el día 25."] = "冬幕节期间，冬天爷爷会在铁炉堡和奥格瑞玛发礼物，25 日那天树下还会出现礼包。",
	["En el Festival de la Cosecha, la Horda honra a Grom Grito Infernal y la Alianza a Uther, en sus monumentos."] = "收获节期间，部落在纪念碑前缅怀格罗姆·地狱咆哮，联盟则缅怀乌瑟尔。",
	["En el Núcleo de Magma se desuellan perros del núcleo para un cuero muy especial."] = "在熔火之心可以剥熔火恶犬的皮，得到一种非常特别的皮革。",
	["En el Santuario Esmeralda, los druidas intentan sanar el bosque enfermo."] = "在翡翠圣地，德鲁伊们努力治愈生病的森林。",
	["En el Valle de Alterac pelean la Guardia Pico Tormenta de los enanos y el clan Lobo Gélido. Yo ya sé a quién le voy."] = "在奥特兰克山谷，矮人的雷矛卫队与霜狼氏族交战。我早就知道我要支持谁了。",
	["En el Valle de la Fuerza están el banco y la casa de subastas: el corazón del comercio de la Horda."] = "力量谷有银行和拍卖行：部落贸易的中心。",
	["En el camino"] = "顺路",
	["En el centro de aquel Kalimdor estaba el Pozo de la Eternidad, un lago de pura magia. Unos trols que vivían a su orilla cambiaron con los siglos y se volvieron los elfos de la noche."] = "在远古的卡利姆多中心，有一片纯粹魔法构成的湖泊：永恒之井。住在湖畔的一些巨魔经过数百年的变化，成了暗夜精灵。",
	["En el centro de la garganta hay un enorme pozo de lava, la Caldera, donde trabajan esclavos de los Hierro Negro."] = "峡谷中央有一个巨大的熔岩坑，叫做大熔炉，黑铁矮人的奴隶在那里劳作。",
	["En el centro del cráter humea un volcán donde viven elementales de fuego."] = "火山口中央有一座冒着烟的火山，里面住着火元素。",
	["En el chat"] = "在聊天框中",
	["En el corazón del Templo de la Luna hay un pozo lunar, donde las sacerdotisas rezan a Elune."] = "月神殿的中心有一口月亮井，女祭司们在那里向艾露恩祈祷。",
	["En el cráter, un tal Linken perdió la memoria y busca su espada y su escudo: un guiño a cierto héroe de orejas puntiagudas."] = "在火山口里，一个叫林克的家伙失去了记忆，正在寻找他的剑和盾：这是在向某位尖耳朵英雄致敬。",
	["En el este de las Tierras Inhóspitas viven dragones negros y sus siervos. Pasa lejitos si no llevas compañía."] = "荒芜之地东部住着黑龙和他们的仆从。如果你独自一人，就离远点。",
	["En el este del lago viven ogros que les hacen la vida difícil a los enanos de Thelsamar."] = "湖的东边住着食人魔，让塞尔萨玛的矮人们日子很不好过。",
	["En el gran salar del este, goblins y gnomos organizan carreras; la rivalidad es feroz."] = "在东边的大盐滩上，地精和侏儒举办赛车；竞争非常激烈。",
	["En el juego"] = "在游戏中",
	["En el lago de Villa del Lago hay múrlocs, ¡como en casi todo lago de Azeroth!"] = "湖畔镇的湖里有鱼人，艾泽拉斯几乎每个湖里都有！",
	["En el mapa"] = "在地图上",
	["En el mapa de Alfa, clic: seguirla con la flecha o guardarla como marcador."] = "在 Alfa 的地图上点击：用箭头跟随它，或将其保存为标记。",
	["En el mapa del mundo"] = "在世界地图上",
	["En el marco del objetivo"] = "在目标框体上",
	["En el minimapa"] = "在小地图上",
	["En el mundo"] = "野外",
	["En el nivel 10 domas tu bestia."] = "10 级时可以驯服你的野兽。",
	["En el nivel 20 aprendes venenos."] = "20 级时学会毒药。",
	["En el norte de estas tierras, la Cruzada Escarlata domina un pueblo amurallado y lo defiende con fanatismo."] = "在这片土地的北部，血色十字军占据着一座有城墙的城镇，狂热地守卫着它。",
	["En el oeste de Las Mil Agujas anidan dracoleones salvajes."] = "千针石林西部栖息着野生的双足飞龙。",
	["En el pueblo de los druidas del Claro de la Luna conviven Alianza y Horda: el Círculo Cenarion recibe a todos."] = "在月光林地的德鲁伊村庄里，联盟和部落和平共处：塞纳里奥议会欢迎所有人。",
	["En el sur de Desolace, demonios y sátiros se reúnen en un aquelarre."] = "在凄凉之地南部，恶魔和萨特聚在一起举行集会。",
	["En el sur de Tanaris hay colmenas de silítidos, primos de los de Silithus."] = "塔纳利斯南部有异种虫的巢穴，跟希利苏斯的是亲戚。",
	["En el sureste, la Mano de Tyr es la ciudad más fuerte que le queda a la Cruzada Escarlata."] = "在东南方，提尔之手是血色十字军仅存的最强城市。",
	["En espera"] = "等待中",
	["En esta zona"] = "在此区域",
	["En estas laderas está Durnholde, donde Aedelas Blackmoore crió a Thrall como gladiador."] = "敦霍尔德就在这些山坡上，埃德拉斯·布莱克摩尔在那里把萨尔培养成角斗士。",
	["En estas tierras cayó Anduin Lothar, el León de Azeroth, durante la Segunda Guerra."] = "“艾泽拉斯之狮”安度因·洛萨在第二次战争中倒在了这片土地上。",
	["En estas tierras estuvo Strom, la capital de Arathor, el primer gran reino humano."] = "这片土地上曾经矗立着斯托姆，那是第一个伟大的人类王国阿拉索的首都。",
	["En este pantano se hundió el Templo de Atal'Hakkar: los dragones verdes lo hundieron para frenar a los sacerdotes de Hakkar."] = "阿塔哈卡神庙沉入了这片沼泽：绿龙让它沉没，以阻止哈卡的祭司。",
	["En grupo"] = "组队时",
	["En grupo casi siempre hay varios enemigos: pegas a dos a la vez."] = "组队时几乎总有多个敌人：你能同时打两个。",
	["En grupo y aguantando: Furia justa te da más amenaza."] = "组队坦怪时：正义之怒让你产生更多威胁。",
	["En grupo, cura al tanque antes que a nadie."] = "组队时，优先治疗坦克。",
	["En grupo, cura al tanque primero y no saques monstruos tú."] = "组队时，先治疗坦克，别自己去拉怪。",
	["En grupo, cura antes de que la vida baje mucho: es más barato."] = "组队时，在血量掉太多之前就治疗：更省法力。",
	["En grupo, deja tus tótems de maná y de curas cerca del grupo."] = "组队时，把法力图腾和治疗图腾放在队伍附近。",
	["En la Arena Gurubashi aparece de vez en cuando un cofre que todos se pelean. ¡Sálvese quien pueda!"] = "古拉巴什竞技场时不时会出现一个宝箱，大家都抢着要。各凭本事吧！",
	["En la Enciclopedia"] = "在百科中",
	["En la Feria canjeas vales por premios; los vales se ganan entregando cosas que hiciste con tu profesión o que juntaste cazando."] = "在马戏团里可以用奖券兑换奖品；交出你用专业制作或狩猎收集的东西就能赚奖券。",
	["En la Feria de la Luna Negra, la adivina Sayge te hace unas preguntas y te da una fortuna que sube tus estadísticas un buen rato."] = "在暗月马戏团，算命师塞格会问你几个问题，然后给你一份运势，在一段时间内提升你的属性。",
	["En la Fortaleza de Grommash, Thrall recibe a quien venga; muy cerca está Eitrigg, el viejo orco amigo de Tirion."] = "在格罗玛什要塞，萨尔接见所有来访者；附近站着埃特里格，那位和提里奥结为好友的老兽人。",
	["En la Guerra de las Arenas Movedizas, el archidruida Fandral perdió a su hijo Valstann a manos de los qiraji."] = "在流沙之战中，大德鲁伊范达尔的儿子瓦斯坦恩死于其拉虫人之手。",
	["En la Segunda Guerra, la Horda sumó a los trols Amani, a los ogros y a dragones rojos esclavizados."] = "第二次战争中，阿曼尼巨魔、食人魔和被奴役的红龙加入了部落。",
	["En la Semana de los Niños, los huérfanos de Ventormenta y Orgrimmar te piden que los lleves de paseo; al final te dan una mascota."] = "儿童周期间，暴风城和奥格瑞玛的孤儿会请你带他们出去玩；最后他们会送你一只宠物。",
	["En la Tercera Guerra, orcos, humanos y elfos se unieron aquí contra Archimonde, y Nordrassil sacrificó su energía para destruirlo."] = "第三次战争中，兽人、人类和精灵在这里联手对抗阿克蒙德，诺达希尔牺牲了自己的能量摧毁了他。",
	["En la Terraza de los Artesanos de Darnassus están los maestros de profesiones."] = "达纳苏斯的工匠区有各专业的训练师。",
	["En la Vega se encuentran páginas sueltas de un libro de Nesingwary; junta un capítulo completo y llévaselo."] = "在荆棘谷可以找到奈辛瓦里一本书的散页；凑齐完整的一章交给他。",
	["En la batalla de Hyjal, Malfurion hizo sonar el Cuerno de Cenarius y miles de fuegos fatuos rodearon a Archimonde hasta destruirlo."] = "在海加尔山之战中，玛法里奥吹响了塞纳留斯之角，成千上万的小精灵包围了阿克蒙德，直到将他摧毁。",
	["En la casa de subastas, mira los precios unos días antes de vender: cambian según la hora y quién esté jugando."] = "在拍卖行卖东西之前，先观察几天价格：价格会随时段和在线的人而变化。",
	["En la cima del Monte Hyjal crece Nordrassil, el Árbol del Mundo, que los dragones bendijeron."] = "世界之树诺达希尔生长在海加尔山顶，受过巨龙的祝福。",
	["En la costa de Durotar, soldados de Kul Tiras ocupan el Fuerte Tiragarde: una espina clavada en la tierra de la Horda."] = "在杜隆塔尔的海岸，库尔提拉斯士兵占据着提拉加德城堡：这是扎在部落土地上的一根刺。",
	["En la costa de Tanaris se esconden piratas de los Mares del Sur."] = "塔纳利斯的海岸上藏着南海海盗。",
	["En la costa del pantano hay naga, y no reciben bien a los curiosos."] = "沼泽的海岸上有纳迦，他们不欢迎好奇的人。",
	["En la costa este vive una tribu trol amiga de la Horda, enemiga de los trols de Jintha'Alor."] = "东海岸住着一个与部落友好的巨魔部族，他们与辛萨罗的巨魔为敌。",
	["En la costa oeste de Vallefresno, las Cavernas de Brazanegra fueron un templo de Elune; hoy están hundidas y llenas de naga."] = "在灰谷西海岸，黑暗深渊曾是一座艾露恩神殿；如今它已沉没，到处是纳迦。",
	["En la costa se ven ruinas de antiguos palacios élficos, medio hundidos en el mar."] = "沿着海岸可以看到古代精灵宫殿的遗迹，一半沉在海里。",
	["En la cueva del barco hay muchos piratas: no bajen todos de golpe al muelle."] = "停船的洞穴里有很多海盗：别一下子全跳到码头上。",
	["En la excavación de Ironband, los troggs salieron de la tierra y se quedaron con todo."] = "在铁环挖掘场，穴居人从地底钻出来，把一切都占了。",
	["En la granja de los Saldean, la vieja yegua Blanchy necesita avena. Es de las misiones más tiernitas de los Páramos."] = "在萨丁农场，老马布兰契需要燕麦。这是西部荒野最温馨的任务之一。",
	["En la guarida de Onyxia, a los lados hay nidos con huevos: si alguien los pisa salen dragoncitos... muchísimos."] = "在奥妮克希亚的巢穴两侧有满是蛋的巢：要是有人踩到，就会冒出雏龙……非常多。",
	["En la pelea, el juego te avisa"] = "战斗中，游戏会提醒你",
	["En la sala de la Liga de Expedicionarios de Forjaz hay biblioteca, mapas y un museo con fósiles gigantes."] = "铁炉堡的探险者协会大厅有图书馆、地图和一座陈列巨大化石的博物馆。",
	["En la segunda parte mátenla a ella primero: cura mucho."] = "第二阶段先杀她：她的治疗量很大。",
	["En la subasta cuenta el precio más bajo que vio, menos la comisión (%d%%, estimada). Al desencantar usa tablas del juego clásico, también estimadas."] = "拍卖按看到的最低价减去抽成（%d%%，估计）计算。分解则使用经典旧世的数据表，同样是估计值。",
	["En la subasta, unos %s."] = "拍卖行大约 %s。",
	["En la ventana y aquí. Si no estás entre ellos, tu fila sale al final."] = "在窗口和这里显示。如果你不在其中，你的那一行会显示在最后。",
	["En las Cuevas de los Lamentos, el druida Naralex soñó con devolverle el verdor a Los Baldíos, y su sueño se volvió pesadilla."] = "在哀嚎洞穴，德鲁伊纳拉雷克斯梦想让贫瘠之地重现绿意，他的梦却变成了噩梦。",
	["En las Guerras Trol, los altos elfos enseñaron magia a cien humanos para vencer juntos a los Amani. Fueron los primeros magos de la humanidad."] = "在巨魔战争中，高等精灵把魔法教给一百名人类，一起击败阿曼尼。他们是人类最早的法师。",
	["En las Mazmorras de Ventormenta los presos se amotinaron, y la guardia pide ayuda para calmar el desastre."] = "暴风城监狱的囚犯发动了暴乱，卫兵正在找人帮忙平息乱局。",
	["En las Pozas de la Visión, bajo una de las mesetas, entrenan los magos y sacerdotes Renegados."] = "在其中一座台地下方的预见之池，被遗忘者的法师和牧师在那里训练。",
	["En las cuevas de Cuna del Invierno viven yetis peludos y gruñones."] = "冬泉谷的洞穴里住着毛茸茸、脾气暴躁的雪人。",
	["En las cuevas de Feralas viven yetis, y los ogros Gordunni tienen sus campamentos en el norte."] = "菲拉斯的洞穴里住着雪人，戈杜尼食人魔在北边扎营。",
	["En las cuevas nevadas de Dun Morogh viven trols de las nieves que no quieren a los enanos ni tantito."] = "丹莫罗的雪洞里住着冰霜巨魔，他们一点也不喜欢矮人。",
	["En las dos armas"] = "两把武器都有",
	["En las granjas del oeste hay calderos de la Plaga que siguen esparciendo la peste; la Alianza manda aventureros a destruirlos."] = "西边的农场里有天灾军团的瘟疫大锅，仍在散播瘟疫；联盟派冒险者去摧毁它们。",
	["En las ruinas de la ciudad de Alterac hoy mandan los ogros y el Sindicato, la banda de nobles caídos del viejo reino."] = "如今统治奥特兰克城废墟的是食人魔和辛迪加，后者是旧王国没落贵族组成的帮派。",
	["En lo alto de la sierra hay un pico sagrado para los druidas elfos, donde anidan aves enormes."] = "山脉高处有一座精灵德鲁伊的圣峰，巨大的鸟在那里筑巢。",
	["En lo más alto de la Montaña Roca Negra manda Nefarian, hijo de Alamuerte."] = "统治黑石山最高处的是死亡之翼之子奈法利安。",
	["En los mapas"] = "在地图上",
	["En lugar de las del juego"] = "替代游戏背包",
	["En marcha"] = "进行中",
	["En marcha hacia %s"] = "正在前往%s",
	["En mazmorra"] = "在地下城中",
	["En mazmorras y bandas"] = "在地下城和团队副本中",
	["En memoria"] = "纪念",
	["En memoria de una gran perrita"] = "纪念一只很棒的小狗",
	["En mi zona"] = "在我的区域",
	["En movimiento"] = "动态",
	["En orco, «Lok'tar ogar» quiere decir «victoria o muerte»."] = "在兽人语中，“Lok'tar ogar”的意思是“不胜利，毋宁死”。",
	["En otra zona: %s"] = "在其他区域：%s",
	["En pantalla"] = "显示中",
	["En pausa"] = "已暂停",
	["En pausa dentro de la instancia"] = "副本中暂停",
	["En pausa por ahora"] = "暂时暂停",
	["En pausa: hay otro addon de pesca activo"] = "已暂停：另一个钓鱼插件正在启用",
	["En plena Segunda Guerra, Gul'dan abandonó a la Horda para buscar la Tumba de Sargeras. Ahí lo despedazaron los demonios que encontró."] = "第二次战争正激烈时，古尔丹抛下部落去寻找萨格拉斯之墓。他在那里被遇到的恶魔撕成了碎片。",
	["En posadas y ciudades acumulas XP descansada: ganas el doble de XP por enemigo hasta gastarla. Si cierras sesión aquí, también se acumula."] = "在旅店和城镇中会累积精力充沛经验：击杀敌人获得双倍经验，直到用完。在这里下线也会累积。",
	["En posadas y ciudades juntas XP descansada: ganas el doble por enemigo hasta gastarla."] = "在旅店和城市中会累积休息经验：每个敌人获得双倍经验，直到用完。",
	["En qué orden aparecen."] = "显示的顺序。",
	["En qué se gastan"] = "用在哪里",
	["En silencio"] = "静音",
	["En solitario es lento: usa la varita para rematar."] = "单人时杀怪较慢：用魔杖收尾。",
	["En solitario, deja curas que duran en el tiempo y pelea con Cólera."] = "单人时，挂上持续治疗，用愤怒战斗。",
	["En solitario, pelea con choques y cúrate entre monstruos."] = "单人时，用震击战斗，打怪间隙给自己治疗。",
	["En su ficha toca «Agregar a mi ruta»."] = "在它的详情页点击“加入我的路线”。",
	["En sus inicios, una batalla del Valle de Alterac podía durar horas... ¡y hasta días!"] = "早期的奥特兰克山谷，一场战斗能打上好几个小时……甚至好几天！",
	["En tu arma"] = "武器上已有",
	["En tu marco"] = "在你的框体上",
	["En tu plan"] = "在你的计划中",
	["En tu registro"] = "在你的任务日志中",
	["En tus bolsas"] = "在你的背包中",
	["En tus bolsas, el botín, el chat o cualquier enlace: Alt+clic abre la guía para conseguirlo o, si no hay, su ficha en la enciclopedia."] = "在背包、战利品、聊天或任何链接中：Alt+点击可打开获取它的指南；如果没有，则打开它在百科中的详情页。",
	["En tus bolsas: úsala para aprenderla"] = "在你的背包中：使用它来学会",
	["En un aviso"] = "以提醒显示",
	["En un aviso y en el chat"] = "以提醒显示并发到聊天框",
	["En un cañón de Vallefresno, Grom mató al señor demonio Mannoroth y liberó a los orcos de su sangre maldita."] = "在灰谷的一处峡谷中，格罗姆杀死了恶魔领主玛诺洛斯，让兽人摆脱了他被诅咒的血液。",
	["En un valle de Frondavil cayeron infernales del cielo, y todavía se ven sus cráteres."] = "费伍德森林的一座山谷里曾有地狱火从天而降，至今还能看到它们砸出的坑。",
	["En un vuelo con escalas, una línea bajo el temporizador dice dónde es la siguiente parada y cuánto falta para llegar. Necesita el temporizador de vuelo encendido."] = "在有中转的飞行中，计时器下方会显示下一站在哪里以及还要多久到达。需要开启飞行计时器。",
	["En una aldea del sur del bosque, los vecinos parecen normales de día... y de noche se convierten en worgen."] = "在森林南部的一座村庄，村民白天看起来很正常……到了晚上就会变成狼人。",
	["En una de las mesetas, los tauren honran a los espíritus de sus ancestros."] = "在其中一座台地上，牛头人祭拜祖先的灵魂。",
	["En una instancia: la flecha vuelve al salir"] = "在副本中：离开后箭头会恢复",
	["En una isla de Azshara vive el duque Hydraxis, señor del agua; su gente te ayuda a apagar las runas del Núcleo de Magma."] = "水元素领主海达克西斯公爵住在艾萨拉外海的一座岛上；他的手下会帮你熄灭熔火之心的符文。",
	["En una pestaña nueva"] = "在新标签页中",
	["En unos segundos aparece tu build."] = "几秒后就会显示你的方案。",
	["En uso"] = "使用中",
	["En uso, a tu gusto"] = "使用中，按你的喜好",
	["En vivo"] = "实时",
	["En vivo si estás con un banquero; si no, la última foto."] = "在银行职员旁时为实时内容；否则显示最后的快照。",
	["En vuelo: la flecha sigue al bajar"] = "飞行中：降落后箭头会继续",
	["En vuelo: la flecha sigue al bajar."] = "飞行中：降落后箭头会继续指引。",
	["Enanos"] = "矮人",
	["Encanta tu arma antes de pelear."] = "战斗前为武器附魔。",
	["Encantada"] = "已附魔",
	["Encantamiento"] = "附魔",
	["Encantar a otros es un servicio: anúnciate en el chat de comercio de la ciudad."] = "为别人附魔是一项服务：在城里的交易频道打广告吧。",
	["Encender el registro"] = "开启记录",
	["Encender la pesca"] = "开启钓鱼",
	["Encender las recomendadas"] = "开启推荐项",
	["Encender una fogata"] = "点燃篝火",
	["Encenderla"] = "开启",
	["Encenderlos"] = "开启",
	["Encendida: entra al plan aunque el filtro la deje fuera. Apagada: queda fuera."] = "开启：即使被筛选条件排除也会加入计划。关闭：不加入。",
	["Encendido"] = "已开启",
	["Encendido: el doble clic mientras pescas lanza de nuevo y, con Mayús, Ctrl o Alt, recoge. Apagado: al revés."] = "开启：钓鱼时双击会重新抛竿，按住 Shift、Ctrl 或 Alt 双击则收竿。关闭：反过来。",
	["Enciclopedia"] = "百科",
	["Enciende las comodidades recomendadas"] = "开启推荐的便利功能",
	["Enciende los cambios de abajo en el cuadro que sale al pasar el ratón por un personaje o criatura."] = "对鼠标指向角色或生物时出现的鼠标提示启用下方的改进。",
	["Enciende los cambios de abajo en el probador (Ctrl + clic en un objeto)."] = "对试衣间（Ctrl + 点击物品）启用下方的改进。",
	["Enciende los cambios de abajo; cada uno se puede apagar por separado. Algunos addons acomodan sus botones al cuadrado después de /reload."] = "启用下方的改进，每一项都可以单独关闭。部分插件在 /reload 后才会把按钮调整到方形小地图上。",
	["Enciende primero la guía en el minimapa."] = "请先开启小地图上的指南。",
	["Enciende primero los servicios."] = "请先开启服务。",
	["Enciéndela para ver en combate qué habilidad conviene ahora y cuáles siguen, en un ícono pequeño que puedes mover."] = "开启后，战斗中会在一个可移动的小图标里显示现在该用哪个技能以及接下来用哪些。",
	["Enciéndelo en el menú del juego: Opciones > %s > «%s». Alfa no lo cambia por ti: el medidor del juego lo lee en combate y fallaría."] = "请在游戏菜单中开启：选项 > %s > “%s”。Alfa 不会替你更改：游戏的伤害统计会在战斗中读取它，改了会出错。",
	["Enciéndelos abajo, en Marcos, para ver a tu grupo con su vida y curar con un clic."] = "在下方的“框体”中开启，即可查看队友的生命值并一键治疗。",
	["Enciéndelos en la página Curación."] = "在“治疗”页面中开启。",
	["Enciéndelos para ver a tu grupo con su vida y curar con un clic."] = "开启后可查看队伍的生命值，并一键治疗。",
	["Enemigo raro"] = "稀有敌人",
	["Enemigos menores"] = "次要敌人",
	["Enfoque interno: tu siguiente hechizo es gratis y más crítico."] = "心灵专注：你的下一个法术免费且更容易暴击。",
	["Enraíza al monstruo y aléjate antes de lanzar tus hechizos largos."] = "先定住怪物，拉开距离后再施放读条长的法术。",
	["Entendido"] = "知道了",
	["Entereza"] = "真言术：韧",
	["Entorno"] = "环境",
	["Entra al juego con él una vez."] = "用它登录游戏一次。",
	["Entra con el registro limpio: entrega lo que ya tienes."] = "带着整洁的任务日志进去：先交付你已有的任务。",
	["Entra en el plan que termina y entrega tus misiones por el camino más corto, con lo que pide antes."] = "加入以最短路线完成并交付你的任务的计划，连同它需要先做的事。",
	["Entrada"] = "入口",
	["Entrada enemiga"] = "敌方入口",
	["Entradas de mazmorras"] = "地下城入口",
	["Entradas en el minimapa"] = "小地图上的入口",
	["Entradas y salidas"] = "入口与出口",
	["Entraron %s, con lo que piden antes de entregarlas."] = "已加入 %s，以及交付前需要先做的事。",
	["Entraste a %s"] = "你进入了%s",
	["Entraste a %s."] = "你进入了%s。",
	["Entrañas son las criptas y catacumbas bajo la antigua capital de Lordaeron."] = "幽暗城是洛丹伦旧都地下的墓穴和地下墓窟。",
	["Entrañas tiene barrios para magos, pícaros, guerreros y boticarios, y en el anillo central están el banco y la casa de subastas."] = "幽暗城有法师、盗贼、战士和药剂师各自的区域，中央环区有银行和拍卖行。",
	["Entre Entrañas y Grom'gol también hay zepelín: así bajas al sur sin cruzar todo el continente."] = "幽暗城和格罗姆高之间也有飞艇：这样不用横穿整片大陆就能南下。",
	["Entre los druidas están los de la Garra, que se vuelven osos, y los del Espolón, que toman forma de cuervo."] = "德鲁伊中有会变成熊的利爪德鲁伊，也有会化身乌鸦的猛禽德鲁伊。",
	["Entrega tus %d misiones listas"] = "交付你已完成的 %d 个任务",
	["Entregada"] = "已交付",
	["Entregar"] = "交付",
	["Entregar %s"] = "交付%s",
	["Entregar las completadas"] = "交付已完成的任务",
	["Entregar las misiones de tu guía"] = "交付指南中的任务",
	["Entregar mis misiones"] = "交付我的任务",
	["Entregar misiones"] = "交付任务",
	["Entregar solas las misiones de la guía"] = "自动交付指南中的任务",
	["Entregar todas"] = "全部交付",
	["Entregarla"] = "交付它",
	["Entregarlas ahora"] = "现在交付",
	["Entrenador"] = "训练师",
	["Entrenador al día"] = "训练已是最新",
	["Entrenador de %s"] = "%s训练师",
	["Entrenador de tu clase"] = "你的职业训练师",
	["Entrenador: %s, en %s."] = "训练师：%s，位于%s。",
	["Entrenador: %s."] = "训练师：%s。",
	["Entrenadores de profesión"] = "专业训练师",
	["Entrenar"] = "训练",
	["Entrenar la rápida"] = "学习快速骑术",
	["Entrégala a %s."] = "交给%s。",
	["Entró %s, con lo que pide antes de entregarla."] = "已加入 %s，以及交付前需要先做的事。",
	["Envenena y lanza rayos: quita el veneno si puedes."] = "他会施毒并施放闪电：能驱毒就驱掉。",
	["Equilibrada"] = "均衡",
	["Equilibrado"] = "均衡",
	["Equilibrado: se ve bien y corre bien en casi cualquier equipo."] = "均衡：画面好看，几乎在任何电脑上都运行流畅。",
	["Equilibrio"] = "平衡",
	["Equilibrio para subir"] = "平衡（升级）",
	["Equipa tu caña de pescar"] = "装备你的鱼竿",
	["Equipo"] = "装备",
	["Equipo %d %%"] = "装备 %d %%",
	["Equipo a punto de romperse."] = "装备快要损坏了。",
	["Equipo de pesca"] = "钓鱼装备",
	["Equipo y cebos"] = "装备与鱼饵",
	["Equipo y estadísticas"] = "装备与属性",
	["Equipo, consumibles, misiones, materiales... con encabezados que se pliegan."] = "装备、消耗品、任务物品、材料……标题可折叠。",
	["Equitación"] = "骑术",
	["Equitación de aprendiz (nivel 40)"] = "初级骑术（40 级）",
	["Equitación de oficial (la rápida, nivel 60)"] = "中级骑术（快速，60 级）",
	["Eranikus, el consorte de Ysera, quedó atrapado en la pesadilla; su sombra ronda el Templo de Atal'Hakkar."] = "伊瑟拉的配偶伊兰尼库斯被困在梦魇中；他的阴影在阿塔哈卡神庙中徘徊。",
	["Eres de la manada"] = "你是狼群的一员",
	["Eres nivel %d"] = "你的等级是 %d",
	["Eres nivel %d y se recomienda el %d: desde ahí cuenta así."] = "你是 %d 级，推荐 %d 级：从那里开始这样计算。",
	["Eres nivel %d."] = "你的等级是 %d。",
	["Error"] = "错误",
	["Errores de Lua de Alfa en esta sesión:"] = "本次游戏中 Alfa 的 Lua 错误：",
	["Errores de Lua de Alfa en esta sesión: ninguno"] = "本次游戏中 Alfa 的 Lua 错误：无",
	["Es corta y está dentro de Ventormenta. Los presos están en celdas a los lados: avancen despacio."] = "副本很短，就在暴风城里面。囚犯关在两侧的牢房里：慢慢推进。",
	["Es de la otra facción"] = "属于另一阵营",
	["Es de una misión."] = "这是任务物品。",
	["Es el jefe que pide una misión de la Alianza: revisa tus misiones antes de entrar."] = "这是联盟某个任务要求击杀的首领：进去前检查一下你的任务。",
	["Es el primer jefe y es sencillo. Al morir, el prisionero de tu facción abre la puerta del patio."] = "这是第一个首领，很简单。他死后，本阵营的囚犯会打开通往庭院的门。",
	["Es el primer reto: con él se abre el Legado."] = "这是第一个挑战：完成后传承就会开启。",
	["Es el punto %d de %d de tu build."] = "这是你方案的第 %d/%d 点。",
	["Es el que toca ahora."] = "现在该点这个。",
	["Es el último del Cementerio. Lanza llamas a su alrededor: si peleas de lejos, quédate lejos."] = "墓地的最后一个首领。会向四周喷射火焰：远程玩家请站远一点。",
	["Es el único lobo a la vista."] = "视野中只有这一只狼。",
	["Es grande y es fácil perderse: sigan a una sola persona y no corran solos."] = "副本很大，容易迷路：跟紧一个人，别单独乱跑。",
	["Es la máquina de Sneed: rómpela y él saldrá a pelear."] = "这是斯尼德的机器：把它打坏，他就会出来战斗。",
	["Es la primera mazmorra de la Horda: corta y buena para aprender a jugar en grupo."] = "部落的第一个地下城：很短，适合学习组队玩法。",
	["Es la primera mazmorra grande de la Alianza: avancen despacio y tiren un grupo a la vez."] = "联盟的第一个大型地下城：慢慢推进，一次只拉一群怪。",
	["Es larga y tiene dos entradas. Muchos enemigos son de piedra y pegan fuerte."] = "副本很长，有两个入口。很多敌人是石头做的，打人很痛。",
	["Es larga y tiene muchos robots: algunos ponen bombas o hacen sonar alarmas que traen más enemigos."] = "副本很长，机器人很多：有些会放炸弹，或拉响警报引来更多敌人。",
	["Es lento: si peleas de lejos, atácalo mientras se acerca."] = "他移动很慢：远程玩家可以趁他靠近时输出。",
	["Es muy veloz: frénalo si tu clase puede."] = "他速度很快：如果你的职业能减速就减速他。",
	["Es opcional. Si dices que sí, los lobos de La Jauría que usan Alfa ven a tu personaje en el mapa de WoW, como ves a tu grupo, y pueden llegar a donde estás con la flecha; y tú a ellos. Alfa solo comparte dónde anda tu personaje dentro del juego: la zona, el punto en el mapa, su nivel y su clase. Nada de tu ubicación real, tu computadora ni tu cuenta."] = "这是可选的。如果你同意，使用 Alfa 的 La Jauría 狼群成员就能在 WoW 地图上看到你的角色，就像你看到自己的队伍一样，还能用箭头找到你；你也能找到他们。Alfa 只分享你的角色在游戏中的位置：区域、地图上的点、等级和职业。绝不涉及你的真实位置、你的电脑或你的账号。",
	["Es opcional: tu personaje aparece en el mapa de WoW de los lobos de La Jauría que usan Alfa, y ellos en el tuyo, para encontrarse y llegar con la flecha. Solo se comparte dónde anda tu personaje dentro del juego (zona, punto en el mapa, nivel y clase), nunca tu ubicación real ni nada de tu computadora, y nunca dentro de mazmorras. Tu grupo se ve siempre. Lo cambias cuando quieras en La Jauría."] = "这是可选的：你的角色会出现在使用 Alfa 的 La Jauría 狼群成员的 WoW 地图上，他们也会出现在你的地图上，方便互相找到并用箭头前往。只分享你的角色在游戏中的位置（区域、地图上的点、等级和职业），绝不分享你的真实位置或你电脑上的任何东西，在地下城中也绝不分享。你的队伍总是可见。随时可以在 La Jauría 中更改。",
	["Es para niveles %s y vas en el %d: te faltan %d niveles."] = "适合 %s 级，你是 %d 级：还差 %d 级。",
	["Es para otra raza."] = "适用于其他种族。",
	["Es raro del Cementerio y no siempre aparece."] = "墓地的稀有首领，不一定会出现。",
	["Es raro del Cementerio y no siempre aparece. Envenena: quita el veneno."] = "墓地的稀有首领，不一定会出现。会施毒：记得驱毒。",
	["Es raro del Cementerio y no siempre aparece. Puede silenciar a quien lanza hechizos."] = "墓地的稀有首领，不一定会出现。能沉默施法者。",
	["Es raro y aparece pocas veces. Usa fuego a su alrededor."] = "稀有首领，很少出现。会在身边释放火焰。",
	["Es raro y está en una cueva escondida. Es un murciélago que pega rápido."] = "稀有首领，在一个隐蔽的洞穴里。是一只攻击很快的蝙蝠。",
	["Es raro y no siempre aparece. Pega muy fuerte para su nivel: tírenlo con cuidado."] = "稀有首领，不一定会出现。以他的等级来说打人非常痛：拉怪时要小心。",
	["Es raro y no siempre está. Golpea fuerte a todos los que tiene enfrente."] = "稀有首领，不一定在。会重击面前的所有人。",
	["Es raro. Pone un tótem de tierra: rómpelo."] = "稀有首领。会放下大地图腾：打掉它。",
	["Es raro: no siempre está. Duerme a los jugadores y explota con magia a su alrededor."] = "稀有首领：不一定在。会催眠玩家，并在身边引发魔法爆炸。",
	["Es sencillo: buen momento para beber agua antes del último jefe."] = "很简单：正好趁打最终首领前喝口水。",
	["Es un brujo que lanza hechizos: interrúmpelo si tu clase puede (Patada, Golpe de escudo, Choque de tierra...)."] = "他是施法者：如果你的职业能打断就打断他（脚踢、盾击、地震术……）。",
	["Es un chamán con tótems: rompan los tótems, son fáciles de matar."] = "他是带图腾的萨满：打掉图腾，它们很容易打。",
	["Es un enano con escudo: aguanta mucho pero no tiene trucos."] = "持盾的矮人：很耐打，但没什么特殊技能。",
	["Es un enemigo fuerte de la mina: trátenlo como un jefe pequeño."] = "矿洞里的强力敌人：把他当成小首领来打。",
	["Es un grupo: cada uno suelta su propio botín."] = "这是一组敌人：每个都会掉落自己的战利品。",
	["Es un paladín: se cura con luz sagrada. Interrumpe su curación."] = "他是圣骑士，会用圣光术治疗自己。打断他的治疗。",
	["Es un sátiro rápido que envenena: si tu clase quita venenos, úsalo."] = "动作很快的萨特，会施毒：如果你的职业能驱毒，就用上。",
	["Es un trogg que lanza rayos: interrúmpelo."] = "会施放闪电的穴居人：打断他。",
	["Es una mejora para ti"] = "对你是提升",
	["Es una montura de tu clase: pregunta a tu instructor de clase cuándo y cómo se consigue."] = "这是你职业专属的坐骑：问问你的职业训练师何时以及如何获得。",
	["Es una tortuga gigante con mucha armadura: pega lento pero duro."] = "护甲很厚的巨龟：攻击慢但很痛。",
	["Es una tortuga muy dura, pero solo golpea: no tiene trucos."] = "非常耐打的乌龟，但只会普通攻击：没什么特殊技能。",
	["Esa cadena no trae ninguna estadística que Alfa puntúe."] = "该字符串中没有 Alfa 可评分的属性。",
	["Esa fila todavía no se abre: faltan puntos en esa rama."] = "那一排还没解锁：该系天赋的点数不够。",
	["Esa tecla ya tiene dueño"] = "这个按键已被占用",
	["Esbirros enemigos"] = "敌方仆从",
	["Escala de estadísticas"] = "属性权重",
	["Escalas:"] = "中转站：",
	["Escaneando..."] = "扫描中...",
	["Escanear ahora"] = "立即扫描",
	["Escanear con Alfa"] = "用 Alfa 扫描",
	["Escaneo completo: %s objetos con precio (%s subastas)."] = "完整扫描：%s 种物品有价格（%s 件拍卖品）。",
	["Escarcha"] = "冰霜",
	["Escarcha para subir"] = "冰霜（升级）",
	["Esconde las placas y los nombres de los PNJ mientras pescas (los enemigos hostiles conservan su nombre), para ver y tocar mejor el corcho."] = "钓鱼时隐藏 NPC 的姓名板和名字（敌对目标仍显示名字），让鱼漂更容易看见和点到。",
	["Esconde lo que pide más habilidad de la que tienes. Sin esto se ve gris y tenue."] = "隐藏技能要求高于你当前技能的采集点。不勾选时会以灰色淡化显示。",
	["Escribe %s o haz clic en el lobo del minimapa para abrirla. Empieza en Hoy, con lo que toca a tu clase; %s muestra u oculta la ventana de guía."] = "输入 %s 或点击小地图上的狼即可打开。窗口先显示“今天”，列出你的职业需要的东西；%s 可显示或隐藏指南窗口。",
	["Escribe %s y cuéntanos en el Discord de La Jauría."] = "输入 %s，然后在 La Jauría 的 Discord 告诉我们。",
	["Escribe al menos dos letras."] = "请至少输入两个字。",
	["Escribe arriba el nombre de una mazmorra para buscarla."] = "在上方输入地下城名称进行搜索。",
	["Escribe cuánto oro (1 o más)."] = "输入多少金币（1 或以上）。",
	["Escribe el número que quieras y presiona Enter."] = "输入你想要的数字，然后按 Enter。",
	["Escribe el top %d en el chat de tu grupo o banda."] = "在你的小队或团队聊天中发布前 %d 名。",
	["Escribe en el chat del grupo cuando terminas un objetivo de una misión compartida. Viene apagado para no llenar el chat de nadie."] = "完成共享任务的一个目标时，在队伍聊天中发言。默认关闭，以免刷屏。",
	["Escribe tu nota."] = "写下你的备注。",
	["Escribe un nivel (2 o más)."] = "输入一个等级（2 或以上）。",
	["Escribe un nombre corto para reconocerla."] = "输入一个简短的名字，方便辨认。",
	["Escribir a %s"] = "给%s发消息",
	["Escuchar"] = "试听",
	["Escuchar el aullido"] = "试听狼嚎",
	["Escudo"] = "盾牌",
	["Escudo de relámpagos"] = "闪电之盾",
	["Escudo y defensa: aguantas a todos los monstruos para que tu grupo no sufra."] = "盾牌和防御：扛住所有怪物，让队友不受伤害。",
	["Escudo y luz sagrada: un tanque muy resistente que recupera su propio maná."] = "盾牌加神圣之光：一个非常耐打、能自己回复法力值的坦克。",
	["Escudos y curas preventivas: aguantas mucho y apoyas al grupo."] = "护盾和预防性治疗：非常耐打，还能支援队伍。",
	["Ese build es para otra clase."] = "这个方案是给其他职业的。",
	["Ese talento necesita antes otro talento completo (la flecha del árbol)."] = "这个天赋需要先点满另一个天赋（天赋树中的箭头）。",
	["Ese texto es demasiado largo para un build."] = "这段文字太长，不是有效的方案。",
	["Ese texto es demasiado largo para una cadena de escala."] = "该文本过长，不是有效的权重字符串。",
	["Ese texto no es una ruta de Alfa."] = "这段文字不是 Alfa 路线。",
	["Esmeralda"] = "翡翠",
	["Eso no es una cadena de build de Alfa. Empieza con ALFA1;"] = "这不是 Alfa 的方案字符串。它应该以 ALFA1; 开头",
	["Eso no es una cadena de escala de estadísticas. Empieza con ( Pawn: v1: \"Nombre\": ..."] = "这不是属性权重字符串。它以 ( Pawn: v1: \"名称\": ... 开头",
	["Eso se puede al salir de combate."] = "脱离战斗后才能这样做。",
	["Espacio"] = "空格",
	["Espacio libre"] = "剩余空间",
	["Espacio y dinero"] = "空间和金钱",
	["Espada de dos manos"] = "双手剑",
	["Espada de una mano"] = "单手剑",
	["Espalda"] = "背部",
