	["Furia para grupo"] = "组队狂怒战",
	["Furia para pelear contra jugadores: muchísimo daño, Ira rabiosa mejorada contra el miedo e Interceptar más seguido para no soltar al rival."] = "为 PvP 打造的狂怒战：伤害极高，强化狂暴之怒对付恐惧，更频繁的拦截让对手无处可逃。",
	["Furia sangrienta te da más ira para empezar peleas difíciles."] = "血性狂暴给你更多怒气，用来开打难缠的战斗。",
