	["Modo historia: 1 jefe por descubrir. Vence a cada uno para ver su nombre y su botín (puedes apagarlo en Ajustes)."] = "剧情模式：还有 1 个首领待发现。击败每个首领即可看到其名字和战利品（可在设置中关闭）。",
