	["Novedades de Alfa %s"] = "Alfa %s 新内容",
	["Nozdormu, el Atemporal, cuida el curso del tiempo. Dicen que conoce el día de su propia muerte, y aun así sigue con su deber."] = "永恒者诺兹多姆守护着时间的流动。据说他知道自己死去的那一天，却依然坚守职责。",
	["Nuestra manada en Discord: ayuda, avisos y reportes. Haz clic en el enlace y cópialo con Ctrl+C."] = "我们在 Discord 上的狼群：帮助、公告和问题反馈。点击链接后用 Ctrl+C 复制。",
