	["Ocultar los botones del chat"] = "隐藏聊天按钮",
	["Ocultar los grifos de la barra de acción"] = "隐藏动作条两侧的狮鹫",
	["Ocultar los marcos de grupo de Blizzard"] = "隐藏暴雪的团队框体",
