	["Ocultarlo en combate"] = "战斗中隐藏",
	["Ocultas"] = "隐藏",
	["Ocultas como en el juego, reveladas, o reveladas con un tono más frío para saber dónde no has estado."] = "像游戏中一样隐藏、全部显示，或用偏冷的色调显示，让你知道哪里还没去过。",
	["Oculto en el modelo."] = "已在模型上隐藏。",
