	["Ojo con tu plan"] = "注意你的计划",
	["Ojo con tu ruta"] = "注意你的路线",
	["Ojo de pescador"] = "渔夫之眼",
	["Ojo por aquí: %s tiene sus sorpresas."] = "这里要小心：%s可藏着不少惊喜。",
	["Ojo: tu clic para lanzar de Blizzard usa %d de estas teclas, y ese manda también aquí. Para igualarlos, usa «Usar también en los marcos de Blizzard»."] = "注意：你的暴雪点击施法占用了其中 %d 个按键，而且在这里也以它为准。想让两边一致，请使用“也用于暴雪框体”。",
	["Ojo: tu equipo anda al %d%%. Un herrero te lo deja como nuevo."] = "注意：你的装备耐久度只剩 %d%%。找铁匠修一下就跟新的一样。",
	["Olas y superficie del agua. Llega hasta Ultra (3) y no más: valores mayores pueden cerrar el juego, por eso Alfa no los deja."] = "波浪与水面。最高到“极高（3）”：更高的数值可能导致游戏崩溃，所以 Alfa 不允许。",
	["Olor a fogata"] = "篝火的烟味",
	["Olvidar"] = "忘记",
	["Olvidar mi progreso aquí"] = "忘记我在这里的进度",
	["Omite este paso: la guía sigue con el siguiente. Puedes volver a él con Anterior."] = "跳过此步骤：指南会继续下一步。你可以用“上一步”返回。",
	["Omite este paso: la guía sigue con el siguiente. Puedes volver a él desde «Ver detalle»."] = "跳过此步骤：指南会继续下一步。你可以从“查看详情”回到这一步。",
	["Omitir"] = "跳过",
