	["Quienes usan Alfa y comparten te ven en su mapa y pueden seguirte, y tú a ellos. Se envía tu zona, tu posición, tu nivel y tu clase cada 10 segundos mientras te mueves (cada 4 minutos si estás quieto), nunca dentro de mazmorras ni por canales públicos."] = "使用 Alfa 并共享位置的人能在地图上看到你并跟随你，你也能看到他们。移动时每 10 秒发送一次你的区域、位置、等级和职业（静止时每 4 分钟一次），在地下城内或通过公共频道绝不发送。",
