	["Tu posición y la del cursor bajo el mapa."] = "在地图下方显示你和光标的位置。",
	["Tu primer punto, en el nivel 10."] = "10 级时获得第一个天赋点。",
	["Tu primer talento"] = "你的第一个天赋",
	["Tu primera guía"] = "你的第一个指南",
	["Tu primera montura (nivel 40)"] = "你的第一匹坐骑（40 级）",
	["Tu primera sesión entra al diario cuando salgas del juego. La manada te espera: ¡a cazar!"] = "退出游戏后，你的第一次游戏记录会写入日志。狼群在等你：出发狩猎吧！",
	["Tu prioridad"] = "你的优先级",
	["Tu prioridad: %s"] = "你的优先级：%s",
	["Tu progreso"] = "你的进度",
	["Tu propia lista de metas, en el orden que quieras: un objeto, oro, una profesión, un lugar, una misión, un nivel o una nota. Alfa las mide solas y te lleva a cada una."] = "你自己的目标清单，顺序随你定：物品、金币、专业、地点、任务、等级或备注。Alfa 会自动追踪，并带你前往每一个。",
	["Tu propio marco aparece aunque no estés en grupo, para curarte con un clic."] = "即使不在队伍中也显示你自己的框体，方便一键治疗自己。",
	["Tu prueba"] = "你的测试",
	["Tu rama: %s"] = "你的天赋系：%s",
	["Tu rastro"] = "你的踪迹",
	["Tu ratón"] = "你的鼠标",
