	["Usarlo"] = "使用",
	["Usas las bolsas del juego"] = "你使用游戏背包",
	["Uso: /alfa comercio precio <enlace del objeto>"] = "用法：/alfa comercio precio <物品链接>",
	["Uso: /alfa recoleccion [ruta [mineria|hierbas|pesca|tesoros] | guiar | parar | mapa | minimapa]"] = "用法：/alfa recoleccion [ruta [mineria|hierbas|pesca|tesoros] | guiar | parar | mapa | minimapa]",
	["Uso: /alfa silenciar <número>, /alfa silenciar quitar <número>, /alfa silenciar borrar."] = "用法：/alfa silenciar <编号>、/alfa silenciar quitar <编号>、/alfa silenciar borrar。",
	["Vaciar"] = "清空",
	["Vaelastrasz, un dragón rojo, está preso de Nefarian en la Guarida Alanegra. Antes de pelear contra ti, te presta su fuerza."] = "红龙瓦拉斯塔兹是奈法利安囚禁在黑翼之巢的俘虏。在与你战斗之前，他会把自己的力量借给你。",
	["Valor de %s: llevas %s"] = "价值%s：目前 %s",
	["Valor de bloqueo"] = "格挡值",
	["Valor de lo pescado"] = "渔获价值",
	["Valor de venta"] = "出售价格",
	["Valor en la subasta"] = "拍卖价格",
	["Valor exacto"] = "精确数值",
	["Variable del juego: %s"] = "游戏变量：%s",
	["Varimathras sirve a Sylvanas en Entrañas. Es un señor del terror, así que nadie sabe cuánto le va a durar la lealtad."] = "瓦里玛萨斯在幽暗城为希尔瓦娜斯效力。他是个恐惧魔王，所以没人知道他的忠诚能维持多久。",
	["Varios"] = "其它",
	["Varios enemigos cerca: Nova sagrada los golpea a todos."] = "附近有多个敌人：神圣新星可以击中所有敌人。",
	["Varios enemigos cerca: el cono los golpea y los frena."] = "附近有多个敌人：冰锥术会击中并减速它们。",
	["Varios enemigos cerca: el tótem de magma los quema a todos."] = "附近有多个敌人：熔岩图腾会灼烧所有敌人。",
	["Varios enemigos cerca: golpéalos a todos a la vez."] = "附近有多个敌人：同时攻击它们。",
	["Varios enemigos cerca: la ola los golpea y los frena."] = "附近有多个敌人：冲击波会击中并减速它们。",
	["Varios enemigos juntos: el huracán los golpea a todos."] = "多个敌人聚在一起：飓风会击中所有敌人。",
	["Varios enemigos juntos: la ventisca los golpea a todos."] = "多个敌人聚在一起：暴风雪会击中所有敌人。",
	["Varios enemigos juntos: lluvia de fuego sobre ellos."] = "多个敌人聚在一起：对它们施放火焰之雨。",
	["Varios enemigos juntos: quémalos a todos a la vez."] = "多个敌人聚在一起：一次把它们全部烧掉。",
	["Varios enemigos: consagra el suelo bajo ti."] = "多个敌人：在脚下施放奉献。",
	["Varios enemigos: el disparo alcanza a varios."] = "多个敌人：这次射击能命中多个目标。",
	["Varios enemigos: el rayo salta entre ellos."] = "多个敌人：闪电会在它们之间跳跃。",
	["Varios enemigos: golpéalos a todos."] = "多个敌人：攻击它们全部。",
	["Varios enemigos: tus golpes alcanzan a otro más."] = "多个敌人：你的攻击会多命中一个。",
	["Varita"] = "魔杖",
	["Vas en %d de %d"] = "进度 %d / %d",
	["Vas muy bien. Cada paso cuenta, aunque no lo parezca."] = "你做得很好。每一步都算数，即使看起来不像。",
	["Vas tras %s"] = "你正在追踪%s",
	["Veces completada"] = "完成次数",
	["Veces completadas"] = "完成次数",
	["Vegetación"] = "植被",
	["Velen, Kil'jaeden y Archimonde guiaban a los eredar. Los dos últimos aceptaron el poder de Sargeras; Velen huyó."] = "维伦、基尔加丹和阿克蒙德曾领导艾瑞达人。后两者接受了萨格拉斯的力量；维伦则逃走了。",
	["Velocidad"] = "速度",
	["Velocidad del zoom"] = "缩放速度",
	["Vence a este jefe para descubrir su nombre y su botín."] = "击败此首领即可揭晓其名字和战利品。",
	["Vence a sus jefes para ver lo que sueltan, o apaga el modo historia en Ajustes."] = "击败它的首领即可看到掉落，或在设置中关闭剧情模式。",
	["Vencido"] = "已击败",
	["Vendas para curarte sin gastar maná ni esperar: imprescindible para todos."] = "用绷带治疗自己，不耗法力也不用等：人人必备。",
	["Vende"] = "出售",
	["Vende cañas y cebos"] = "出售鱼竿和鱼饵",
	["Vende lo gris cada vez que pases por un pueblo: es oro fácil y libera espacio."] = "每次经过城镇都卖掉灰色物品：既是轻松的金币，又能腾出空间。",
	["Vende lo gris con cualquier vendedor o tira algo que ya no uses."] = "把灰色物品卖给任意商人，或丢掉不再用的东西。",
	["Vende lo que no usas y junta lo que cuesta aprender a montar."] = "卖掉不用的东西，攒够学骑术需要的钱。",
	["Vende los materiales en montones de 20 o de 10: así es como la gente los compra."] = "材料按 20 个或 10 个一组出售：大家都是这样买的。",
	["Vende los objetos grises y lo que marcaste como basura. Nunca lo que marcaste para guardar."] = "出售灰色物品和你标记为垃圾的物品。绝不出售你标记为保留的物品。",
	["Vendedor"] = "商人",
	["Vendedor de monturas de tu raza"] = "你种族的坐骑商人",
