	["Venenos"] = "毒药",
	["Venenos y críticos: matas rápido, sobre todo atacando por la espalda."] = "毒药加暴击：杀得很快，尤其是从背后攻击时。",
	["Ventana de guía oculta. Escribe /alfa guia para volver a verla."] = "指南窗口已隐藏。输入 /alfa guia 可重新显示。",
