	["Ventura y Cía. abrió minas en Mulgore sin pedir permiso, y a los tauren eso no les hace ninguna gracia."] = "风险投资公司没经允许就在莫高雷开矿，牛头人对此可一点都不高兴。",
	["Ventura y Cía. tala y mina la Sierra Espolón sin piedad, y los druidas hacen lo que pueden por detenerla."] = "风险投资公司在石爪山脉毫无节制地伐木开矿，德鲁伊们正尽力阻止他们。",
	["Ventura y Cía. trae máquinas enormes para talar los árboles más viejos de la sierra."] = "风险投资公司运来巨大的机器，砍伐山里最古老的树木。",
