	["¡%d misiones entregadas hoy! Así se caza en manada."] = "今天已经交了 %d 个任务！狼群就是这样狩猎的。",
	["¡%d misiones hoy! Estás que no te para nadie."] = "今天完成了 %d 个任务！谁也挡不住你。",
	["¡%s!"] = "%s！",
	["¡%s! Hace días que no te veía. En Hoy te digo dónde íbamos."] = "%s！好几天没见到你了。在“今天”里我会告诉你我们上次到哪儿了。",
	["¡Abrumar!"] = "压制！",
	["¡Ahí estás, %s! Si quieres un consejo, dame clic."] = "你在这儿呀，%s！想要建议就点我。",
	["¡Arriba, lobo! Antes de volver a pelear, recupera vida y maná."] = "起来吧，狼！再次战斗之前，先恢复生命值和法力值。",
	["¡Arriba, lobo! Caer es parte de la cacería. Al revivir, repara tu equipo."] = "起来吧，狼！倒下也是狩猎的一部分。复活后记得修理装备。",
	["¡Arriba, lobo! Libera tu espíritu: la flecha te dice si conviene tu cuerpo o el sanador."] = "起来吧，狼！释放灵魂：箭头会告诉你是回到尸体更划算，还是找灵魂医者。",
	["¡Arriba, lobo! Si eran muchos, la próxima jálalos de uno en uno."] = "起来吧，狼！如果怪太多，下次一只一只地拉。",
	["¡Arriba, nivel %d! Si tienes un punto de talento libre, no lo olvides."] = "升到 %d 级了！如果有未分配的天赋点数，别忘了。",
	["¡Así se ve un aviso!"] = "提醒就是这个样子！",
	["¡Ataque de la victoria!"] = "乘胜追击！",
	["¡Bien hecho! %s"] = "干得好！%s",
	["¡Buen día, %s! El sol ya salió en Azeroth. ¿Vamos?"] = "早安，%s！艾泽拉斯的太阳已经升起来了。走吧？",
	["¡Buenas noches, %s! Las lobas cazamos mejor de noche."] = "晚上好，%s！我们母狼在夜里最会狩猎。",
	["¡Buenas tardes, %s! Buena hora para unas misiones."] = "下午好，%s！正是做几个任务的好时候。",
	["¡Buenas, %s! Paso a paso se llega lejos."] = "你好，%s！一步一步就能走得很远。",
	["¡Buenos días, %s! Me estiro, bostezo y estoy lista."] = "早上好，%s！伸个懒腰，打个哈欠，我准备好啦。",
	["¡Completaste %s!"] = "你完成了%s！",
	["¡Contraataque!"] = "反击！",
	["¡De vuelta con la manada!"] = "欢迎回到狼群！",
	["¡Ejecutar!"] = "斩杀！",
	["¡En Thelsamar venden morcilla! La morcilla de Thelsamar es casi una salchicha... ¿me compras una?"] = "塞尔萨玛有卖血肠！塞尔萨玛血肠差不多就是香肠了……给我买一根好吗？",
	["¡Es ahora! Hasta las %s"] = "就是现在！持续到 %s",
	["¡Hola!"] = "你好！",
	["¡Hola! Soy Lya, la loba de confianza del Alfa. Cuido a la manada y voy contigo en el camino."] = "你好！我是 Lya，Alfa 最信任的母狼。我守护狼群，也会陪你一路同行。",
	["¡Hola, %s!"] = "你好，%s！",
	["¡Hola, %s! Hoy huele a buena cacería."] = "你好，%s！今天闻起来是个狩猎的好日子。",
	["¡Hola, %s! La tarde pinta tranquila. ¿Qué cazamos hoy?"] = "你好，%s！今天下午看起来很平静。我们去猎点什么？",
	["¡Hola, %s! Noche de luna: perfecta para la manada."] = "你好，%s！月夜——最适合狼群了。",
	["¡Listo! %s precios guardados."] = "完成！已保存 %s 个价格。",
	["¡Listo! Alfa ya es tuyo"] = "完成！Alfa 已经属于你",
	["¡Lo tienes! %s ×%d"] = "到手了！%s ×%d",
	["¡Martillo de cólera!"] = "愤怒之锤！",
	["¡Mordedura de mangosta!"] = "猫鼬撕咬！",
	["¡Nivel %d! Date un momento para presumirlo, te lo ganaste."] = "%d 级了！花点时间炫耀一下吧，这是你应得的。",
	["¡Nivel %d! Paso firme y colmillo afilado."] = "%d 级了！脚步稳健，獠牙锋利。",
	["¡Nivel %d! Tu esfuerzo se nota. Sigue así."] = "%d 级了！你的努力看得见。继续保持。",
	["¡Nivel %d! ¡Auuu! Así se sube en manada."] = "%d 级了！嗷呜——狼群就是这样升级的。",
	["¡Nivel %d, bien hecho! Revisa si tu entrenador tiene algo nuevo."] = "%d 级了，干得好！看看你的训练师有没有新东西。",
	["¡Nivel 10! Ya tienes talentos: elígelos con calma, Talentos te ayuda."] = "10 级了！你有天赋了：慢慢选，“天赋”会帮你。",
	["¡Nivel 20! Ya puedes con mazmorras de verdad. ¿Armamos grupo?"] = "20 级了！你可以挑战真正的地下城了。组个队吧？",
	["¡Nivel 30! Ya vas a la mitad del camino. ¡Qué orgullo de manada!"] = "30 级了！你已经走完一半了。狼群真为你骄傲！",
	["¡Nivel 40! Ya puedes aprender a montar. ¡Tu primera montura te espera!"] = "40 级了！你可以学骑术了。你的第一匹坐骑在等你！",
	["¡Nivel 50! Ya se huele la cima. Junta oro para lo que viene."] = "50 级了！已经闻到顶峰的气息了。为接下来的事攒点金币。",
	["¡Nivel 60! ¡Lo lograste, alfa! Ahora toca cazar en grande."] = "60 级了！你做到了，头狼！现在该来一场大狩猎了。",
	["¡Plan terminado!"] = "计划完成！",
	["¡Primera vez! Nuevo en tu diario"] = "第一次！已加入你的图鉴",
	["¡Qué buena racha traes! Sigue así."] = "你的状态真好！继续保持。",
	["¡Qué bueno tenerte de vuelta, %s! Aquí sigo, cuidándote la espalda."] = "真高兴你回来了，%s！我还在这里守着你的背后。",
	["¡Qué gusto verte de vuelta! Esto es lo que trae esta versión para ti y tu manada."] = "真高兴再次见到你！这是本版本为你和你的狼群带来的内容。",
	["¡Qué gusto verte, %s! La manada ya te esperaba."] = "真高兴见到你，%s！狼群一直在等你。",
	["¡Repara tu equipo!"] = "修理你的装备！",
	["¡Revancha!"] = "复仇！",
	["¡Subiste a nivel %d! Cada nivel te hace más fuerte."] = "你升到了 %d 级！每升一级都让你更强。",
	["¡Te extrañé, %s! Tu ruta sigue donde la dejaste."] = "我好想你，%s！你的路线还在你离开的地方。",
	["¡Terminaste %s!"] = "你完成了%s！",
	["¡Terminaste esta guía! Elige la siguiente y sigue subiendo con la manada."] = "你完成了这个指南！选择下一个，和狼群一起继续升级吧。",
	["¡Terminaste tu guía!"] = "你完成了你的指南！",
	["¡Tú!"] = "你！",
	["¡Volviste, %s! Estira las patas y vámonos."] = "你回来了，%s！伸伸腿，我们出发吧。",
	["¡Ya eres nivel %d! La manada aúlla por ti."] = "你已经 %d 级了！狼群为你嚎叫。",
	["¡Ya terminaste %d misiones! Vamos a cobrar la recompensa."] = "你已经完成了 %d 个任务！我们去领奖励吧。",
	["«%s» tiene su historia. ¿Te la cuento?"] = "“%s”有一段故事。要我讲给你听吗？",
	["«%s» ya quedó. Su final vale la pena, ¿te lo cuento?"] = "“%s”已经完成了。它的结局很值得一听，要我讲给你听吗？",
	["«Alejar más la cámara» de Comodidades está encendido y manda sobre este valor al entrar."] = "便利功能中的“镜头拉得更远”已开启，登录时会覆盖此数值。",
	["«Buscar cerca» en la página Hoy"] = "“今天”页面中的“搜索附近”",
	["«Buscar cerca» te lleva con flecha a lo que necesitas, y «Mis planes» arma tus propias metas, que se marcan solas."] = "“搜索附近”会用箭头带你去你需要的地方，“我的计划”可以制定你自己的目标，完成后会自动勾选。",
	["«Cerrar mis misiones» está al día"] = "“完成我的任务”已是最新",
	["«Igual que Alfa» sigue el estilo de Ajustes > Apariencia y cambia con él."] = "“与 Alfa 相同”会跟随“设置 > 外观”中的风格，并随之变化。",
	["«Prepárame» recoge solo las que ya puedes tomar y te lleva a la entrada."] = "“帮我准备”只会接取你现在能接的任务，并带你去入口。",
	["«Seguir» en La Jauría ya no se suelta cuando tu guía cambia de paso ni cuando vas por tu cuerpo: al terminar, la flecha vuelve con quien sigues."] = "La Jauría 的“跟随”不会在指南换步骤或你跑回尸体时断开：结束后，箭头会重新指向你跟随的人。",
	["«Siempre» sirve si un amigo encantador te ayuda. Las tablas de desencantar son estimadas."] = "如果有附魔师朋友帮忙，可以选“总是”。分解数据表为估计值。",
	["«Ver el siguiente» te deja mirar el paso que viene y lo dice claro; y un solo contador de pasos hechos."] = "“查看下一步”让你先看看接下来的步骤，并清楚标明正在预览；已完成步骤也只用一个计数。",
	["¿Abandonar %d misiones?"] = "放弃 %d 个任务？",
	["¿Abandonar %d misión?"] = "放弃 %d 个任务？",
	["¿Algo raro?"] = "发现异常？",
	["¿Aplicar estos talentos?"] = "应用这些天赋？",
	["¿Borrar el diario?"] = "清除日志？",
	["¿Borrar el historial?"] = "清除历史记录？",
	["¿Borrar esta ruta?"] = "删除此路线？",
	["¿Borrar este build?"] = "删除这个方案？",
	["¿Borrar este plan?"] = "删除此计划？",
	["¿Borrar lo que descubriste?"] = "清除你发现的采集点？",
	["¿Borrar los precios?"] = "删除价格？",
	["¿Borrar todo tu progreso?"] = "删除你的全部进度？",
	["¿Borrar todo tu registro de pesca?"] = "清除你的全部钓鱼记录？",
	["¿Borrar todos tus marcadores?"] = "删除你的所有标记？",
	["¿Cuánto decide Alfa por ti en el camino?"] = "一路上 Alfa 替你做多少决定？",
	["¿Cómo quieres hacerlo?"] = "你想怎么做？",
	["¿Cómo quieres que se vea Alfa?"] = "你希望 Alfa 是什么样子？",
	["¿Empezar el medidor de cero?"] = "要将伤害统计清零吗？",
	["¿Empezar una sesión nueva?"] = "开始新的钓鱼记录？",
	["¿En qué idioma quieres Alfa?"] = "你希望 Alfa 使用哪种语言？",
	["¿Eso que huele es pan de la posada? Mi nariz nunca se equivoca."] = "闻到的是旅店的面包吗？我的鼻子从来不会错。",
	["¿La haces con tu manada o la saltas?"] = "要和狼群一起做，还是跳过？",
	["¿La vuelves a tomar o la sacas de la ruta?"] = "要重新接取，还是从路线中移出？",
	["¿Olvidar a este personaje?"] = "忘记这个角色？",
	["¿Olvidar tu progreso?"] = "忘记你的进度？",
	["¿Otra cosa hoy?"] = "今天还想做点别的？",
	["¿Otra vez?"] = "再来一次？",
	["¿Oíste eso? Nada… solo el viento. Sigamos."] = "你听到了吗？没什么……只是风声。继续走吧。",
	["¿Paramos a comer? Mi panza ya está aullando."] = "停下来吃点东西吧？我的肚子已经在嚎叫了。",
	["¿Por dónde sigues?"] = "接下来去哪里？",
	["¿Quieres cazar con nosotros? Pulsa el botón: Alfa busca a un oficial conectado y te abre un susurro con tu mensaje listo para que lo envíes con Intro."] = "想和我们一起狩猎吗？点击按钮：Alfa 会寻找一位在线的官员，并为你打开填好消息的密语，按回车键即可发送。",
	["¿Quieres que la manada te vea en el mapa del juego?"] = "想让狼群在游戏地图上看到你吗？",
	["¿Qué buscas?"] = "你在找什么？",
	["¿Qué es Alfa?"] = "Alfa 是什么？",
	["¿Qué hace Alfa con comerciantes y viajes?"] = "Alfa 在商人和旅行方面会做什么？",
	["¿Qué hace Alfa con tus misiones?"] = "Alfa 会如何处理你的任务？",
	["¿Qué hacemos hoy?"] = "今天做什么？",
	["¿Qué hago con mis objetos?"] = "我的物品该怎么处理？",
	["¿Qué nos quieres contar?"] = "你想告诉我们什么？",
	["¿Qué quieres hacer hoy?"] = "今天想做什么？",
	["¿Qué quieres hacer?"] = "你想做什么？",
	["¿Qué responde Alfa por ti a otros jugadores?"] = "Alfa 会替你如何回应其他玩家？",
	["¿Qué sigue?"] = "接下来做什么？",
	["¿Reiniciar los gráficos?"] = "重启图形？",
	["¿Sabías que las lobas tenemos el mejor oído de la manada? Bueno, eso digo yo."] = "你知道吗？我们母狼的听力是狼群里最好的。嗯，这是我说的。",
	["¿Sabías que…? Alfa junta tus misiones listas en una sola ruta corta."] = "你知道吗……？Alfa 会把你已完成的任务排成一条短路线。",
	["¿Sabías que…? Alfa tiene tres estilos: Alfa, Clásico WoW y Cristal. Y yo me pongo el que elijas."] = "你知道吗……？Alfa 有三种风格：Alfa、经典 WoW 和玻璃。你选哪种，我就换上哪种。",
	["¿Sabías que…? Alt+clic en un objeto lo abre en la Enciclopedia."] = "你知道吗……？Alt+点击物品就能在百科中打开它。",
	["¿Sabías que…? Buscar cerca te lleva al herrero, al banco o al vuelo más cercano."] = "你知道吗……？“搜索附近”能带你去最近的铁匠、银行或飞行点。",
	["¿Sabías que…? Comercio te dice si algo conviene venderlo, subastarlo o convertirlo."] = "你知道吗……？“交易”会告诉你某样东西是该卖给商人、拍卖还是加工。",
	["¿Sabías que…? Con /alfa reportar le cuentas a toxic3000 de un error o una idea."] = "你知道吗……？用 /alfa reportar 可以把错误或想法告诉 toxic3000。",
	["¿Sabías que…? Con Pesca lanzas y recoges con una sola tecla."] = "你知道吗……？用“钓鱼”只需一个键就能抛竿和收竿。",
	["¿Sabías que…? Con clic derecho sobre mí puedes silenciarme una hora o pedirme menos consejos."] = "你知道吗……？右键点击我，可以让我静音一小时，或让我少给点建议。",
	["¿Sabías que…? Con el botón del minimapa ocultas todo Alfa y lo vuelves a traer."] = "你知道吗……？用小地图按钮可以隐藏整个 Alfa，也能再把它叫回来。",
	["¿Sabías que…? El mapa de Alfa muestra el terreno, tus marcadores y lo que hay cerca."] = "你知道吗……？Alfa 的地图会显示地形、你的标记和附近的东西。",
	["¿Sabías que…? En Bolsas ves tus bolsas, tu banco y lo de todos tus personajes."] = "你知道吗……？在“背包”中可以看到你的背包、银行以及你所有角色的物品。",
	["¿Sabías que…? En La Jauría ves a tu grupo y a la manada que usa Alfa."] = "你知道吗……？在 La Jauría 中可以看到你的队伍和使用 Alfa 的狼群。",
	["¿Sabías que…? En Mis planes armas tu propia lista de metas y la flecha te guía."] = "你知道吗……？在“我的计划”中可以制定自己的目标清单，箭头会为你指路。",
	["¿Sabías que…? En Talentos ves qué talento poner ahora y por qué."] = "你知道吗……？在“天赋”中可以看到现在该点哪个天赋以及原因。",
	["¿Sabías que…? La Enciclopedia te dice dónde sale cada objeto, PNJ o misión."] = "你知道吗……？百科会告诉你每件物品、每个 NPC 或任务在哪里。",
	["¿Sabías que…? La página Hoy te dice qué hacer ahora y lo urgente de tu personaje."] = "你知道吗……？“今天”页面会告诉你现在该做什么，以及你角色的紧急事项。",
	["¿Sabías que…? Mazmorras te dice cuál te toca y cómo prepararte."] = "你知道吗……？“地下城”会告诉你该去哪个以及如何准备。",
	["¿Sabías que…? Recolección te marca en el mapa minerales, hierbas y bancos de peces."] = "你知道吗……？“采集”会在地图上标出矿脉、草药和鱼群。",
	["¿Te conté que mi comida favorita son las salchichas? Ninguna otra cosa se le acerca."] = "我说过我最爱吃的是香肠吗？别的都比不上。",
	["¿Una carrerita hasta allá? Yo gano."] = "比赛跑到那边？我赢定了。",
	["¿Usar tu hechizo nuevo?"] = "使用你的新法术？",
	["¿Usar «%s»?"] = "使用“%s”？",
	["¿Vender, subastar o transformar? (escanear, precio <objeto>)"] = "卖店、拍卖还是加工？（escanear 扫描，precio <物品> 查价）",
	["¿Vender, subastar o transformar? Lo que más oro te deja con cada objeto."] = "卖店、拍卖还是加工？告诉你每件物品怎样最赚钱。",
	["¿Volver a lo de antes?"] = "恢复之前的设置？",
	["¿Ya exploraste todo %s? Siempre queda un rincón por ver."] = "%s你都探索完了吗？总还有角落没看过。",
	["¿Ya hiciste esta mazmorra?"] = "你已经打过这个地下城了吗？",
	["¿qué quieres hacer?"] = "你想做什么？",
	["Ábrela con su botón en la barra de menú del juego: la fila de botones pequeños de abajo a la derecha."] = "用游戏菜单栏上的按钮打开它：就是右下角那排小按钮。",
	["Ábrela con tu tecla de talentos (%s) o desde el menú del juego."] = "用你的天赋键（%s）或从游戏菜单打开它。",
	["Ábrela con tu tecla de talentos o desde el menú del juego."] = "用你的天赋键或从游戏菜单打开它。",
	["Ábrela con tu tecla del Legado (%s) o con su botón en la barra de menú del juego."] = "用你的传承键（%s）或游戏菜单栏上的按钮打开它。",
	["Ábrelo con /alfa o con el lobo del minimapa. Para cambiar algo de esto: /alfa bienvenida."] = "用 /alfa 或小地图上的狼打开它。想更改这些设置：/alfa bienvenida。",
